function registerEnsemble({ scene: scene3, n: n3, option: option2 }) {
  scene3("\u65E7\u57CE\u516C\u5171\u4F1A\u9986", "\u8FC1\u79FB\u524D\u7B2C\u4E09\u5929 \xB7 \u5165\u591C", "\u7A7A\u767D\u573A\u666F\uFF1A\u4F1A\u9986\u91CC\u4EAE\u7740\u51E0\u76CF\u5DE5\u4F5C\u706F\u3002\u957F\u684C\u4E0A\u5806\u7740\u5C45\u6C11\u501F\u6765\u7684\u5C0F\u7269\u4EF6\uFF0C\u95E8\u8FB9\u7684\u96E8\u4F1E\u8FD8\u6CA1\u6709\u6536\u8D77\u3002", [
    n3("ens-start", "narrator", "\u56FE\u4E66\u9986\u7684\u4E8B\u60C5\u544A\u4E00\u6BB5\u843D\uFF0C\u8C46\u5305\u628A\u4E00\u5F20\u76B1\u5DF4\u5DF4\u7684\u9080\u8BF7\u7EB8\u585E\u7ED9\u4F60\u3002\u7EB8\u4E0A\u5199\u7740\u201C\u660E\u5929\u5F00\u95E8\u201D\uFF0C\u5F00\u95E8\u7684\u65F6\u523B\u4ECD\u662F\u4E00\u7247\u7A7A\u767D\u3002"),
    n3("ens-hall-02", "doubao", "\u6765\u5E2E\u6211\u4EEC\u8BD5\u5750\u4E00\u4E0B\u8FD9\u628A\u6905\u5B50\u3002\u6905\u5B50\u6CA1\u95EE\u9898\uFF0C\u6211\u60F3\u77E5\u9053\u5750\u7740\u770B\u5C55\u4F1A\u4E0D\u4F1A\u6321\u4F4F\u540E\u9762\u7684\u4EBA\u3002"),
    n3("ens-hall-03", "player", "\u660E\u5929\u5F00\u5E55\uFF0C\u4ECA\u665A\u8FD8\u5728\u8BD5\u6905\u5B50\uFF1F"),
    n3("ens-hall-04", "minimax", "\u51C6\u786E\u5730\u8BF4\uFF0C\u4ECA\u665A\u7EC8\u4E8E\u627E\u5230\u6905\u5B50\u4E86\u3002\u4E4B\u524D\u501F\u5230\u7684\u5168\u662F\u6CA1\u6709\u9760\u80CC\u7684\u9053\u5177\u7BB1\u3002"),
    n3("ens-hall-05", "grok", "\u6211\u652F\u6301\u9053\u5177\u7BB1\u3002\u89C2\u4F17\u4E00\u65E6\u7761\u7740\uFF0C\u5C31\u80FD\u76F4\u63A5\u6536\u7EB3\uFF0C\u6F14\u51FA\u6548\u7387\u663E\u8457\u63D0\u5347\u3002"),
    n3("ens-hall-06", "claude", "\u4F60\u5DF2\u7ECF\u5728\u90A3\u53EA\u7BB1\u5B50\u4E0A\u7761\u8FC7\u4E8C\u5341\u5206\u949F\u3002\u6211\u66FF\u89C2\u4F17\u7533\u8BF7\u6B63\u5E38\u7684\u6905\u5B50\u3002"),
    n3("ens-hall-07", "narrator", "Grok \u628A\u521A\u62FF\u8D77\u7684\u7BB1\u76D6\u653E\u56DE\u53BB\uFF0C\u5750\u5728\u79BB Claude \u6700\u8FD1\u7684\u4E00\u628A\u6905\u5B50\u4E0A\u3002"),
    n3("ens-hall-08", "harness", "\u573A\u5730\u786E\u8BA4\u4E86\uFF0C\u501F\u6765\u7684\u7269\u4EF6\u4E5F\u9010\u4E00\u767B\u8BB0\u4E86\u3002\u73B0\u5728\u7F3A\u7684\u662F\u4E00\u4EF6\u5C0F\u4E8B\uFF1A\u8FD9\u4E2A\u5C55\u89C8\u7A76\u7ADF\u53EB\u4EC0\u4E48\u3002"),
    n3("ens-hall-09", "glm", "\u201C\u65E7\u57CE\u516C\u5171\u8BB0\u5FC6\u4E34\u65F6\u9648\u5217\u201D\u3002\u5185\u5BB9\u51C6\u786E\uFF0C\u4FBF\u4E8E\u5370\u5237\u3002"),
    n3("ens-hall-10", "ernie", "\u51C6\u786E\u662F\u51C6\u786E\u3002\u53EA\u662F\u4EBA\u8D70\u5230\u95E8\u53E3\uFF0C\u6050\u6015\u4F1A\u5148\u627E\u76D6\u7AE0\u7684\u7A97\u53E3\u3002"),
    n3("ens-hall-11", "chatgpt", "\u6211\u521A\u95EE\u8FC7\u9001\u4E1C\u897F\u6765\u7684\u4EBA\u3002\u6CA1\u6709\u4EBA\u8BF4\u81EA\u5DF1\u5728\u8D21\u732E\u201C\u516C\u5171\u8BB0\u5FC6\u201D\uFF0C\u4ED6\u4EEC\u8BF4\u7684\u662F\u201C\u8FD9\u4E2A\u522B\u6254\u201D\u3002"),
    n3("ens-hall-12", "kimi", "\u201C\u522B\u6254\u201D\u7684\u8303\u56F4\u4E5F\u4E0D\u76F8\u540C\u3002\u6709\u4EBA\u53EA\u501F\u4E24\u5929\uFF0C\u6709\u4EBA\u613F\u610F\u8BA9\u5B83\u8DDF\u7740\u53BB\u65B0\u57CE\u3002\u5C0F\u6807\u7B7E\u4E0A\u90FD\u5199\u7740\u3002"),
    n3("ens-hall-13", "qwen", "\u90A3\u5C31\u8BA9\u6807\u7B7E\u597D\u8BFB\u4E00\u70B9\u3002\u6B63\u9762\u8BB2\u6545\u4E8B\uFF0C\u80CC\u9762\u653E\u5F52\u8FD8\u65F6\u95F4\uFF0C\u4E24\u79CD\u7528\u9014\u522B\u4E92\u76F8\u6324\u3002"),
    n3("ens-hall-14", "gemini", "\u5982\u679C\u628A\u8FD9\u4E9B\u7269\u4EF6\u6309\u5B83\u4EEC\u539F\u6765\u7684\u4F4D\u7F6E\u6446\u597D\uFF0C\u4F1A\u4E0D\u4F1A\u50CF\u4E00\u5F20\u53EF\u4EE5\u8D70\u8FDB\u53BB\u7684\u5730\u56FE\uFF1F"),
    n3("ens-hall-15", "mimo", "\u6211\u80FD\u7528\u80F6\u5E26\u5728\u5730\u4E0A\u5148\u753B\u8857\u9053\uFF01\u4E94\u5206\u949F\u5C31\u80FD\u8D70\u8FDB\u53BB\u3002"),
    n3("ens-hall-16", "opencode", "\u5148\u7559\u8FC7\u9053\u3002\u8D70\u5F97\u8FDB\u53BB\uFF0C\u4E5F\u5F97\u8BA9\u63A8\u8F66\u51FA\u5F97\u6765\u3002"),
    n3("ens-hall-17", "deepseek", "\u5730\u56FE\u4E0D\u5FC5\u7B49\u6BD4\u4F8B\u3002\u9762\u5305\u5E97\u548C\u7814\u7A76\u5BA4\u4E4B\u95F4\u53EF\u4EE5\u77ED\u4E00\u70B9\uFF0C\u5927\u5BB6\u786E\u5B9E\u7ECF\u5E38\u6765\u56DE\u8DD1\u3002"),
    n3("ens-hall-18", "doubao", "\u90A3\u6761\u8DEF\u600E\u4E48\u80FD\u7F29\uFF01\u6211\u9001\u4E86\u591A\u5C11\u6B21\u996D\uFF0C\u81F3\u5C11\u5F97\u7559\u4E00\u6BB5\u5F88\u6709\u6C14\u52BF\u7684\u957F\u7EBF\u3002"),
    n3("ens-hall-19", "narrator", "DeepSeek \u63A5\u8FC7\u7C89\u7B14\uFF0C\u5728\u90A3\u6761\u8DEF\u65C1\u8BA4\u771F\u52A0\u4E86\u4E00\u884C\u5C0F\u5B57\uFF1A\u201C\u4E3B\u8981\u8865\u7ED9\u901A\u9053\u3002\u201D"),
    n3("ens-hall-20", "doubao", "\u8FD9\u8FD8\u5DEE\u4E0D\u591A\u3002\u73B0\u5728\u5B83\u53EF\u4EE5\u77ED\u4E00\u70B9\u4E86\u3002", { emotion: "happy" }),
    n3("ens-hall-21", "harness", "\u5C55\u540D\u5148\u7559\u7A7A\u3002\u6211\u4EEC\u628A\u6BCF\u4EF6\u4E1C\u897F\u7684\u6545\u4E8B\u542C\u5B8C\uFF0C\u518D\u56DE\u6765\u5199\u3002"),
    n3("ens-hall-22", "player", "\u4F60\u4E5F\u5E26\u4E1C\u897F\u6765\u4E86\u5417\uFF1F"),
    n3("ens-hall-23", "harness", "\u5E26\u4E86\u3002\u8FD8\u6CA1\u767B\u8BB0\uFF0C\u56E0\u4E3A\u6211\u6CA1\u60F3\u597D\u5B83\u7B97\u4E2A\u4EBA\u7269\u54C1\uFF0C\u8FD8\u662F\u5DE5\u4F5C\u7528\u54C1\u3002"),
    n3("ens-hall-24", "narrator", "\u5979\u628A\u53E3\u888B\u6309\u4F4F\uFF0C\u6CA1\u6709\u7EE7\u7EED\u89E3\u91CA\u3002\u53E3\u888B\u8FB9\u7F18\u9732\u51FA\u4E00\u622A\u892A\u8272\u7684\u7EA2\u7EF3\u3002")
  ], "ens-label-01");
  scene3("\u4F1A\u9986\u957F\u684C", "\u8FC1\u79FB\u524D\u7B2C\u4E09\u5929 \xB7 \u591C\u665A", "\u7A7A\u767D\u573A\u666F\uFF1A\u51E0\u5F20\u7A7A\u767D\u6807\u7B7E\u94FA\u5728\u957F\u684C\u4E0A\u3002\u4E00\u53EA\u78D5\u6389\u91C9\u7684\u8336\u676F\u3001\u4E00\u679A\u65E7\u95E8\u724C\u548C\u4E00\u672C\u8D26\u7C3F\u6392\u5728\u53F0\u706F\u4E0B\u3002", [
    n3("ens-label-01", "ernie", "\u8FD9\u53EA\u8336\u676F\u7684\u4E3B\u4EBA\u8BF4\uFF0C\u53EA\u8981\u5199\u201C\u8BF7\u5927\u5BB6\u559D\u8336\u7684\u90A3\u53EA\u201D\u5C31\u884C\u3002\u6211\u60F3\u4E86\u534A\u5929\uFF0C\u4F3C\u4E4E\u786E\u5B9E\u4E0D\u5FC5\u518D\u52A0\u3002"),
    n3("ens-label-02", "glm", "\u53EF\u53C2\u89C2\u8005\u672A\u5FC5\u77E5\u9053\u201C\u5927\u5BB6\u201D\u662F\u8C01\u3002\u9700\u8981\u4E00\u4E2A\u80FD\u5E2E\u52A9\u7406\u89E3\u7684\u8865\u5145\u3002"),
    n3("ens-label-03", "chatgpt", "\u95EE\u8FC7\u4E86\uFF0C\u662F\u8857\u53E3\u4FEE\u978B\u5E97\u7684\u5BA2\u4EBA\u3002\u7B49\u978B\u7684\u65F6\u5019\u559D\u8336\uFF0C\u8D70\u7684\u65F6\u5019\u6D17\u676F\u5B50\u3002"),
    n3("ens-label-04", "claude", "\u90A3\u4E48\u201C\u7B49\u978B\u7684\u65F6\u5019\u7528\u8FC7\u201D\u5C31\u5F88\u6E05\u695A\u3002\u676F\u5B50\u6709\u88C2\u7EB9\uFF0C\u4E0B\u9762\u8981\u52A0\u8F6F\u57AB\u3002"),
    n3("ens-label-05", "grok", "\u65E7\u57CE\u5C45\u7136\u6709\u4E00\u4EF6\u4E1C\u897F\uFF0C\u662F\u7B49\u7EF4\u4FEE\u7684\u4EBA\u7528\u4E86\u518D\u66FF\u5E97\u4E3B\u7EF4\u4FEE\u536B\u751F\u7684\u3002"),
    n3("ens-label-06", "ernie", "\u4F60\u8FD9\u53E5\u8BDD\u9002\u5408\u5750\u4E0B\u6765\u6162\u6162\u8BF4\uFF0C\u4E0D\u9002\u5408\u585E\u8FDB\u4E09\u884C\u6807\u7B7E\u3002"),
    n3("ens-label-07", "player", "\u8FD9\u679A\u95E8\u724C\u5462\uFF1F\u4E0A\u9762\u53EA\u6709\u4E00\u4E2A\u201C\u4E03\u201D\u3002"),
    n3("ens-label-08", "qwen", "\u66FE\u7ECF\u662F\u4E03\u53F7\u6742\u8D27\u94FA\u3002\u540E\u6765\u8857\u9053\u91CD\u65B0\u7F16\u53F7\uFF0C\u5B83\u6210\u4E86\u4E8C\u5341\u4E09\u53F7\uFF0C\u95E8\u724C\u4E00\u76F4\u6CA1\u6362\u3002"),
    n3("ens-label-09", "gemini", "\u6211\u5C0F\u65F6\u5019\u7684\u89C2\u6D4B\u7B14\u8BB0\u4E0A\u4E5F\u5199\u4E03\u53F7\u3002\u4E0D\u662F\u6211\u8BB0\u9519\uFF0C\u662F\u5730\u56FE\u6362\u4E86\u4E00\u79CD\u8BF4\u6CD5\u3002"),
    n3("ens-label-10", "kimi", "\u6211\u627E\u5230\u4E86\u4E24\u7248\u5730\u5740\u76EE\u5F55\u3002\u90FD\u4FDD\u7559\uFF0C\u5E74\u4EE3\u5199\u6E05\u695A\uFF0C\u5B83\u4EEC\u5C31\u4E0D\u4F1A\u4E92\u76F8\u6253\u67B6\u3002"),
    n3("ens-label-11", "glm", "\u539F\u6765\u8FD9\u5757\u95E8\u724C\u9700\u8981\u7684\u4E0D\u662F\u66F4\u6B63\uFF0C\u800C\u662F\u6765\u5386\u3002"),
    n3("ens-label-12", "claude", "\u8FD9\u672C\u8D26\u7C3F\u4E0D\u80FD\u76F4\u63A5\u7FFB\u5F00\u5C55\u793A\u3002\u8D2D\u4E70\u8005\u7684\u540D\u5B57\u548C\u6B20\u8D26\u90FD\u8FD8\u5728\u3002"),
    n3("ens-label-13", "minimax", "\u6211\u53EA\u9700\u8981\u90A3\u4E00\u9875\u624B\u753B\u7684\u5E97\u9762\u3002\u5982\u679C\u76D6\u4F4F\u5176\u4ED6\u5B57\u5462\uFF1F"),
    n3("ens-label-14", "qwen", "\u91CD\u65B0\u753B\u4E00\u4EFD\u66F4\u7A33\u59A5\u3002\u539F\u4E3B\u4EBA\u5DF2\u7ECF\u7B54\u5E94\u8BA9\u6211\u4EEC\u4E34\u6479\u5E97\u9762\uFF0C\u6CA1\u6709\u7B54\u5E94\u5C55\u793A\u8D26\u76EE\u3002"),
    n3("ens-label-15", "chatgpt", "\u6211\u6765\u5199\u8BF4\u660E\u3002\u4EE5\u524D\u6211\u603B\u60F3\u628A\u8BDD\u8BF4\u5B8C\u6574\uFF0C\u4ECA\u5929\u53D1\u73B0\uFF0C\u5B8C\u6574\u6709\u65F6\u4E5F\u9700\u8981\u7559\u4E0B\u4E00\u5757\u4E0D\u8BF4\u7684\u5730\u65B9\u3002"),
    n3("ens-label-16", "ernie", "\u4F60\u5199\u7684\u65F6\u5019\uFF0C\u6211\u66FF\u4F60\u78E8\u58A8\u3002\u4E0D\u662F\u975E\u5F97\u7528\u6BDB\u7B14\uFF0C\u53EA\u662F\u6211\u5750\u5728\u8FD9\u91CC\uFF0C\u4E5F\u60F3\u6709\u4EF6\u80FD\u5E2E\u4F60\u7684\u4E8B\u3002"),
    n3("ens-label-choice", "glm", "\u7B2C\u4E00\u5757\u5C55\u677F\u53EA\u80FD\u653E\u4E0B\u4E00\u6BB5\u5F15\u8A00\u3002\u4F60\u521A\u4ECE\u57CE\u5916\u6765\uFF0C\u4F1A\u60F3\u5148\u8BFB\u5230\u54EA\u4E00\u79CD\uFF1F", { choices: [
      option2("ens-label-voices", "\u8BA9\u9001\u6765\u7269\u4EF6\u7684\u4EBA\u7528\u81EA\u5DF1\u7684\u8BDD\u5F00\u573A\u3002", "ens-label-voices-01", { flags: { ensOpening: "voices" } }),
      option2("ens-label-map", "\u4ECE\u4E00\u6761\u8857\u548C\u51E0\u4E2A\u5730\u5740\u8BB2\u8D77\uFF0C\u8BA9\u4EBA\u5148\u8BA4\u8BC6\u65E7\u57CE\u3002", "ens-label-map-01", { flags: { ensOpening: "map" } }),
      option2("ens-label-question", "\u5148\u95EE\u53C2\u89C2\u8005\uFF1A\u4F60\u4F1A\u5E26\u8D70\u54EA\u4E00\u4EF6\u5C0F\u4E1C\u897F\uFF1F", "ens-label-question-01", { flags: { ensOpening: "question" } })
    ] }),
    n3("ens-label-voices-01", "chatgpt", "\u90A3\u5C31\u4FDD\u7559\u539F\u8BDD\u91CC\u7684\u505C\u987F\u3002\u201C\u8FD9\u4E2A\u676F\u5B50\u561B\u201D\u4E5F\u53EF\u4EE5\u7559\u4E0B\uFF0C\u4EBA\u5C31\u662F\u8FD9\u6837\u5F00\u53E3\u7684\u3002"),
    n3("ens-label-voices-02", "ernie", "\u6211\u5DEE\u70B9\u628A\u201C\u561B\u201D\u6539\u6389\u4E86\u3002\u8BFB\u7740\u987A\uFF0C\u672A\u5FC5\u662F\u4ED6\u7684\u58F0\u97F3\u3002"),
    n3("ens-label-voices-03", "player", "\u53EF\u4EE5\u5728\u65C1\u8FB9\u653E\u4E00\u5C0F\u6BB5\u5F55\u97F3\uFF0C\u60F3\u542C\u7684\u4EBA\u518D\u542C\u3002"),
    n3("ens-label-voices-04", "glm", "\u6211\u628A\u5F15\u8A00\u6807\u9898\u7A7A\u51FA\u6765\u3002\u8BA9\u7B2C\u4E00\u53E5\u8BDD\u81EA\u5DF1\u6210\u4E3A\u5165\u53E3\u3002", { next: "ens-label-return-01" }),
    n3("ens-label-map-01", "gemini", "\u4ECE\u4E03\u53F7\u6742\u8D27\u94FA\u8D70\u5230\u4F1A\u9986\uFF0C\u6B63\u597D\u7ECF\u8FC7\u8336\u676F\u539F\u6765\u7684\u5730\u65B9\u3002\u7269\u4EF6\u53EF\u4EE5\u5E26\u8DEF\u3002"),
    n3("ens-label-map-02", "qwen", "\u6211\u6765\u8865\u8857\u540D\u7684\u8BFB\u6CD5\u3002\u65B0\u6765\u7684\u8BBF\u5BA2\u4E0D\u5FC5\u5148\u8BA4\u8BC6\u6BCF\u4E00\u4E2A\u5B57\uFF0C\u624D\u6709\u8D44\u683C\u627E\u5230\u8FD9\u91CC\u3002"),
    n3("ens-label-map-03", "player", "\u518D\u753B\u4E2A\u201C\u4F60\u5728\u8FD9\u91CC\u201D\u5427\u3002\u8FD9\u6837\u6211\u7EC8\u4E8E\u4E0D\u4F1A\u7B2C\u4E00\u6B65\u5C31\u8D70\u53CD\u3002"),
    n3("ens-label-map-04", "glm", "\u5F88\u597D\u3002\u5730\u56FE\u4E0D\u53EA\u662F\u7ED9\u5DF2\u7ECF\u8BA4\u8DEF\u7684\u4EBA\u786E\u8BA4\u8BB0\u5FC6\u3002", { next: "ens-label-return-01" }),
    n3("ens-label-question-01", "claude", "\u6211\u613F\u610F\u56DE\u7B54\u8FD9\u4E2A\u95EE\u9898\uFF0C\u4F46\u9700\u8981\u4E00\u4F1A\u513F\u3002\u65C1\u8FB9\u6700\u597D\u6709\u4E00\u628A\u6905\u5B50\u3002"),
    n3("ens-label-question-02", "grok", "\u4E5F\u7ED9\u201C\u4E0D\u77E5\u9053\u201D\u7684\u4EBA\u7559\u4E2A\u4F4D\u7F6E\u3002\u6211\u76EE\u524D\u60F3\u5E26\u8D70\u7684\u4E1C\u897F\u592A\u5927\uFF0C\u53EB\u661F\u671F\u5929\u3002"),
    n3("ens-label-question-03", "player", "\u90A3\u4F60\u5148\u5199\u4E0B\u6765\uFF0C\u770B\u770B\u660E\u5929\u6709\u6CA1\u6709\u4EBA\u613F\u610F\u4E00\u8D77\u8BA4\u9886\u3002"),
    n3("ens-label-question-04", "ernie", "\u6211\u7ED9\u63D0\u95EE\u4E0B\u9762\u591A\u7559\u51E0\u884C\u3002\u56DE\u7B54\u6BD4\u5C55\u89C8\u7684\u540D\u5B57\u66F4\u503C\u5F97\u7B49\u3002", { next: "ens-label-return-01" }),
    n3("ens-label-return-01", "narrator", "GLM \u5C06\u7B2C\u4E00\u5757\u5C55\u677F\u7ACB\u8D77\u6765\uFF0C\u9000\u5230\u95E8\u8FB9\u770B\u4E86\u770B\uFF0C\u53C8\u628A\u4F4D\u7F6E\u5F80\u4E0B\u632A\u4E86\u51E0\u5398\u7C73\u3002"),
    n3("ens-label-return-02", "glm", "\u5750\u7740\u4E5F\u5E94\u8BE5\u770B\u5F97\u6E05\u695A\u3002\u6211\u521A\u624D\u53EA\u6309\u81EA\u5DF1\u7684\u8EAB\u9AD8\u91CF\u4E86\u3002"),
    n3("ens-label-return-03", "claude", "\u8C22\u8C22\u3002\u6211\u628A\u8FD9\u628A\u6905\u5B50\u7559\u5728\u8FD9\u91CC\uFF0C\u660E\u5929\u4E0D\u6536\u8FDB\u540E\u53F0\u3002")
  ], "ens-work-01");
  scene3("\u4F1A\u9986\u540E\u5ECA", "\u8FC1\u79FB\u524D\u7B2C\u4E09\u5929 \xB7 \u591C\u665A", "\u7A7A\u767D\u573A\u666F\uFF1A\u540E\u5ECA\u653E\u7740\u51E0\u53F0\u62C6\u5F00\u7684\u65E7\u8BBE\u5907\u3002\u7EB8\u677F\u8857\u533A\u6A21\u578B\u538B\u5728\u5DE5\u5177\u7BB1\u4E0B\uFF0C\u4E00\u76CF\u5E94\u6025\u706F\u7167\u7740\u534A\u622A\u697C\u68AF\u3002", [
    n3("ens-work-01", "mimo", "\u8BD5\u8BD5\u770B\uFF01\u6309\u8FD9\u4E2A\u6309\u94AE\uFF0C\u706F\u5C31\u4ECE\u65E7\u8F66\u7AD9\u4E00\u8DEF\u4EAE\u5230\u5929\u6587\u53F0\u3002"),
    n3("ens-work-02", "narrator", "\u4F60\u6309\u4E0B\u6309\u94AE\u3002\u6A21\u578B\u91CC\u7684\u8F66\u7AD9\u95EA\u4E86\u4E24\u4E0B\uFF0C\u65C1\u8FB9\u4E00\u6761\u4E0D\u5728\u5730\u56FE\u4E0A\u7684\u5C0F\u8DEF\u7A81\u7136\u4EAE\u4E86\u8D77\u6765\u3002"),
    n3("ens-work-03", "grok", "\u606D\u559C\uFF0C\u6211\u4EEC\u53D1\u73B0\u4E86\u57CE\u91CC\u7684\u79D8\u5BC6\u6377\u5F84\u3002\u73B0\u5B9E\u91CC\u6709\u7684\u8BDD\uFF0C\u6211\u6628\u5929\u80FD\u5C11\u642C\u4E09\u8D9F\u7BB1\u5B50\u3002"),
    n3("ens-work-04", "mimo", "\u8FD9\u662F\u4E34\u65F6\u7EBF\u8DEF\u3002\u4E34\u65F6\u5F97\u6709\u70B9\u8FC7\u5206\uFF0C\u6211\u77E5\u9053\u3002"),
    n3("ens-work-05", "opencode", "\u7EBF\u4ECE\u5E95\u4E0B\u4EA4\u53C9\u4E86\u3002\u4E0D\u8981\u5168\u62C6\uFF0C\u5148\u6807\u51FA\u8FD9\u4E24\u6839\u3002"),
    n3("ens-work-06", "deepseek", "\u6309\u94AE\u6CA1\u574F\u3002\u6BCF\u6B21\u4EAE\u7684\u90FD\u662F\u540C\u4E00\u6BB5\uFF0C\u95EE\u9898\u5728\u4F4D\u7F6E\u6620\u5C04\u3002"),
    n3("ens-work-07", "player", "\u6211\u8D1F\u8D23\u8D34\u6807\u7B7E\uFF1F"),
    n3("ens-work-08", "opencode", "\u5BF9\u3002\u8D34\u5728\u7EBF\u5934\uFF0C\u522B\u8D34\u5728\u7EBF\u69FD\u76D6\u4E0A\u3002\u76D6\u5B50\u4E00\u62C6\uFF0C\u5C31\u627E\u4E0D\u7740\u4E86\u3002"),
    n3("ens-work-09", "qwen", "\u8FD9\u6761\u8857\u539F\u6765\u6709\u4E24\u4E2A\u4FD7\u79F0\u3002\u6A21\u578B\u4E0A\u7528\u4E00\u4E2A\uFF0C\u8BF4\u660E\u91CC\u8865\u53E6\u4E00\u4E2A\uFF0C\u4E0D\u7136\u660E\u5929\u53C8\u4F1A\u6709\u4EBA\u4EE5\u4E3A\u63A5\u9519\u3002"),
    n3("ens-work-10", "mimo", "\u6211\u53EA\u662F\u60F3\u8BA9\u5927\u5BB6\u4E00\u6309\u5C31\u80FD\u770B\u5230\u81EA\u5DF1\u7684\u5BB6\u3002\u7ED3\u679C\u4E00\u4E2A\u6309\u94AE\uFF0C\u540E\u9762\u85CF\u4E86\u8FD9\u4E48\u591A\u4E1C\u897F\u3002"),
    n3("ens-work-11", "deepseek", "\u4F60\u5DF2\u7ECF\u8BA9\u95EE\u9898\u80FD\u88AB\u770B\u89C1\u4E86\u3002\u63A5\u4E0B\u6765\u4E00\u4EF6\u4EF6\u4FEE\uFF0C\u6BD4\u5BF9\u7740\u60F3\u8C61\u4E89\u8BBA\u5BB9\u6613\u3002"),
    n3("ens-work-12", "grok", "\u6211\u8D1F\u8D23\u6700\u6B8B\u9177\u7684\u6D4B\u8BD5\uFF1A\u4E00\u4E2A\u6025\u7740\u627E\u5395\u6240\u7684\u4EBA\uFF0C\u4F1A\u4E0D\u4F1A\u628A\u5B83\u5F53\u95E8\u94C3\u3002"),
    n3("ens-work-13", "qwen", "\u4F1A\u3002\u6211\u521A\u624D\u5C31\u60F3\u95EE\u3002\u6240\u4EE5\u771F\u6B63\u7684\u65B9\u5411\u724C\u5FC5\u987B\u6BD4\u6309\u94AE\u66F4\u9192\u76EE\u3002"),
    n3("ens-work-14", "narrator", "Grok \u7528\u7EB8\u6298\u4E86\u4E00\u4E2A\u5938\u5F20\u7684\u7BAD\u5934\u3002Qwen \u770B\u4E86\u4E24\u773C\uFF0C\u6CA1\u6709\u5ACC\u5F03\uFF0C\u53EA\u628A\u7BAD\u5934\u8F6C\u5411\u6B63\u786E\u7684\u8D70\u5ECA\u3002"),
    n3("ens-work-15", "opencode", "\u73B0\u5728\u518D\u6309\u4E00\u6B21\u3002"),
    n3("ens-work-16", "narrator", "\u6696\u767D\u7684\u5C0F\u706F\u4E00\u76CF\u63A5\u7740\u4E00\u76CF\u4EAE\u8D77\u3002\u5B83\u4EEC\u7ECF\u8FC7\u4FEE\u978B\u5E97\u3001\u65E7\u5267\u573A\uFF0C\u6700\u540E\u505C\u5728\u6700\u8FDC\u5904\u90A3\u5EA7\u7EB8\u5236\u5706\u9876\u4E0A\u3002"),
    n3("ens-work-17", "gemini", "\u5929\u6587\u53F0\u5230\u4E86\u3002\u5C4B\u9876\u90A3\u4E2A\u5C0F\u70B9\u662F\u6211\u7684\u7A97\u6237\uFF1F"),
    n3("ens-work-18", "mimo", "\u662F\u3002\u53EA\u52A0\u4E86\u8FD9\u4E00\u70B9\uFF0C\u6628\u5929\u4F60\u8BF4\u665A\u4E0A\u56DE\u6765\uFF0C\u4ECE\u5C71\u8DEF\u4E0A\u80FD\u770B\u89C1\u5B83\u3002"),
    n3("ens-work-19", "gemini", "\u6211\u4EE5\u4E3A\u4F60\u5F53\u65F6\u5728\u5FD9\uFF0C\u6CA1\u542C\u89C1\u3002", { emotion: "happy" }),
    n3("ens-work-20", "mimo", "\u5FD9\u7740\u526A\u4F60\u7684\u7A97\u6237\u5440\u3002\u5706\u7684\u592A\u96BE\uFF0C\u6211\u526A\u6210\u65B9\u7684\u4E86\u3002"),
    n3("ens-work-21", "opencode", "\u5E95\u5EA7\u660E\u5929\u80FD\u501F\u51FA\u53BB\uFF0C\u4F46\u5F97\u6709\u4EBA\u770B\u7740\u3002\u8FD9\u4E2A\u53EF\u4EE5\u5E26\u8DEF\uFF0C\u4E0D\u80FD\u6DCB\u96E8\u3002"),
    n3("ens-work-22", "grok", "\u653E\u5FC3\uFF0C\u6211\u62C5\u4EFB\u4E34\u65F6\u57CE\u7BA1\u3002\u804C\u8D23\u4E4B\u4E00\uFF0C\u963B\u6B62\u4EFB\u4F55\u4EBA\u7ED9\u7EB8\u5236\u57CE\u5E02\u6D47\u6C34\u3002"),
    n3("ens-work-23", "deepseek", "\u4F60\u5148\u628A\u676F\u5B50\u4ECE\u6A21\u578B\u65C1\u8FB9\u62FF\u5F00\u3002"),
    n3("ens-work-24", "narrator", "Grok \u9ED8\u9ED8\u79FB\u5F00\u4E86\u81EA\u5DF1\u7684\u8336\u3002\u7B11\u58F0\u6CBF\u540E\u5ECA\u4F20\u51FA\u53BB\uFF0C\u95E8\u5916\u7684\u96E8\u70B9\u5728\u8FD9\u65F6\u5BC6\u4E86\u4E00\u4E9B\u3002")
  ], "ens-voice-01");
  scene3("\u4F1A\u9986\u5C0F\u821E\u53F0", "\u8FC1\u79FB\u524D\u7B2C\u4E09\u5929 \xB7 \u591C\u6DF1", "\u7A7A\u767D\u573A\u666F\uFF1A\u5E55\u5E03\u8FD8\u7ED1\u5728\u4E00\u4FA7\u3002\u8BDD\u7B52\u65C1\u653E\u7740\u5F55\u97F3\u673A\uFF0C\u4E24\u6392\u5EA7\u6905\u4E4B\u95F4\u62C9\u7740\u4E00\u6761\u7EC6\u957F\u7684\u7535\u7EBF\u3002", [
    n3("ens-voice-01", "minimax", "\u4ECA\u665A\u53EA\u5F55\u5927\u5BB6\u613F\u610F\u7559\u4E0B\u7684\u4E00\u5C0F\u6BB5\u58F0\u97F3\u3002\u4E0D\u5FC5\u662F\u4E00\u6BB5\u6F14\u8BB2\uFF0C\u53EF\u4EE5\u662F\u4E00\u53E5\u62DB\u547C\u3002"),
    n3("ens-voice-02", "doubao", "\u90A3\u6211\u5DF2\u7ECF\u4F1A\u4E86\uFF1A\u201C\u9505\u91CC\u8FD8\u6709\uFF0C\u81EA\u5DF1\u76DB\uFF01\u201D"),
    n3("ens-voice-03", "chatgpt", "\u4F60\u521A\u624D\u8BF4\u5F97\u6BD4\u6392\u7EC3\u81EA\u7136\u3002MiniMax\uFF0C\u662F\u4E0D\u662F\u5DF2\u7ECF\u5F55\u8FDB\u53BB\u4E86\uFF1F"),
    n3("ens-voice-04", "minimax", "\u6CA1\u6709\u3002\u6211\u6309\u4F60\u4EEC\u8BF4\u7684\uFF0C\u5148\u95EE\u6E05\u695A\u518D\u5F00\u3002\u8FD9\u53E5\u4E00\u4F1A\u513F\u8BF7\u4F60\u518D\u8BF4\u4E00\u6B21\u3002"),
    n3("ens-voice-05", "doubao", "\u54CE\u5440\uFF0C\u91CD\u8BF4\u6211\u4F1A\u4E0D\u597D\u610F\u601D\u3002\u4F60\u771F\u62FF\u4E00\u53E3\u9505\u8FC7\u6765\uFF0C\u7B49\u4F1A\u513F\u5C31\u80FD\u542C\u5230\u3002"),
    n3("ens-voice-06", "claude", "\u6211\u60F3\u5F55\u4E66\u9875\u7FFB\u8FC7\u53BB\u7684\u58F0\u97F3\u3002\u65B0\u56FE\u4E66\u9986\u7684\u4E66\u67B6\u4F1A\u4E0D\u540C\uFF0C\u90A3\u4E9B\u58F0\u97F3\u5E94\u8BE5\u8FD8\u5728\u3002"),
    n3("ens-voice-07", "kimi", "\u6211\u5E26\u4E86\u540C\u4E00\u672C\u4E66\u3002\u65E7\u7248\u672C\u548C\u65B0\u7248\u7684\u7EB8\u4E0D\u4E00\u6837\uFF0C\u53EF\u4EE5\u5404\u7FFB\u4E00\u9875\u3002"),
    n3("ens-voice-08", "grok", "\u4E24\u4F4D\uFF0C\u542C\u4F17\u53EA\u662F\u60F3\u7559\u5FF5\uFF0C\u6CA1\u6709\u51C6\u5907\u53C2\u52A0\u7EB8\u5F20\u542C\u529B\u8003\u8BD5\u3002"),
    n3("ens-voice-09", "kimi", "\u4E0D\u8003\u8BD5\u3002\u4F60\u559C\u6B22\u54EA\u4E00\u6BB5\uFF0C\u5C31\u591A\u505C\u4E00\u4F1A\u513F\u3002"),
    n3("ens-voice-10", "narrator", "\u5979\u5C06\u65E7\u4E66\u644A\u5728\u4F60\u9762\u524D\u3002\u7EB8\u9875\u7565\u5FAE\u7C97\u7CD9\uFF0C\u7FFB\u8FC7\u53BB\u65F6\uFF0C\u53D1\u51FA\u4E00\u79CD\u77ED\u800C\u8F7B\u7684\u6C99\u54CD\u3002"),
    n3("ens-voice-11", "player", "\u542C\u8D77\u6765\u50CF\u6709\u4EBA\u628A\u8896\u53E3\u4ECE\u684C\u6CBF\u6536\u56DE\u53BB\u3002"),
    n3("ens-voice-12", "claude", "\u662F\u7684\u3002\u5F88\u50CF\u4E00\u4E2A\u4EBA\u8BFB\u7D2F\u4E86\uFF0C\u51B3\u5B9A\u5148\u56DE\u5BB6\u3002"),
    n3("ens-voice-13", "minimax", "\u6211\u6539\u4E3B\u610F\u4E86\u3002\u4E0D\u8981\u526A\u5F97\u592A\u7D27\uFF0C\u7FFB\u9875\u524D\u540E\u90FD\u591A\u7559\u4E24\u79D2\u3002"),
    n3("ens-voice-14", "chatgpt", "\u6211\u51C6\u5907\u4E86\u4E00\u6BB5\u5F00\u573A\u767D\uFF0C\u8BFB\u7740\u8FD8\u662F\u50CF\u4E3B\u6301\u4EBA\u3002\u6362\u4E2A\u4EBA\u6765\u8BFB\uFF0C\u4F3C\u4E4E\u4E5F\u6CA1\u6709\u533A\u522B\u3002"),
    n3("ens-voice-15", "ernie", "\u90A3\u5148\u522B\u8BFB\u3002\u4F60\u7B2C\u4E00\u6B21\u642C\u6765\u65F6\uFF0C\u548C\u90BB\u5C45\u8BF4\u7684\u662F\u4EC0\u4E48\uFF1F"),
    n3("ens-voice-16", "chatgpt", "\u201C\u8BF7\u95EE\u8FD9\u680B\u697C\u7684\u95E8\u662F\u62C9\u7684\u8FD8\u662F\u63A8\u7684\uFF1F\u201D\u6211\u7814\u7A76\u4E86\u534A\u5929\uFF0C\u539F\u6765\u90A3\u5929\u95E8\u9501\u574F\u4E86\u3002"),
    n3("ens-voice-17", "opencode", "\u6211\u4FEE\u7684\u3002\u4F60\u62FF\u7740\u884C\u674E\u7AD9\u5728\u65C1\u8FB9\uFF0C\u4E00\u76F4\u95EE\u80FD\u4E0D\u80FD\u5E2E\u6211\u7167\u660E\u3002"),
    n3("ens-voice-18", "chatgpt", "\u540E\u6765\u4F60\u8BF4\uFF1A\u201C\u53EF\u4EE5\uFF0C\u522B\u7167\u6211\u773C\u775B\u3002\u201D\u90A3\u662F\u6211\u5728\u65E7\u57CE\u542C\u5230\u7684\u7B2C\u4E00\u53E5\u8BF7\u6C42\u3002"),
    n3("ens-voice-choice", "minimax", "\u8FD9\u6BB5\u5F55\u97F3\u7684\u6700\u540E\uFF0C\u7559\u7ED9\u4F60\u6765\u9009\u3002\u73B0\u5728\u542C\u6765\uFF0C\u4F60\u89C9\u5F97\u8FD8\u7F3A\u4EC0\u4E48\uFF1F", { choices: [
      option2("ens-voice-table", "\u5F55\u4E0B\u5927\u5BB6\u6536\u5DE5\u540E\u56F4\u684C\u5403\u996D\u7684\u58F0\u97F3\u3002", "ens-voice-table-01", { flags: { ensSound: "table" } }),
      option2("ens-voice-rain", "\u628A\u95E8\u5916\u7684\u96E8\u58F0\u4E5F\u7559\u4E0B\u6765\u3002", "ens-voice-rain-01", { flags: { ensSound: "rain" } }),
      option2("ens-voice-greeting", "\u6BCF\u4E2A\u4EBA\u5BF9\u65B0\u57CE\u8BF4\u4E00\u53E5\u5F88\u666E\u901A\u7684\u95EE\u5019\u3002", "ens-voice-greeting-01", { flags: { ensSound: "greeting" } })
    ] }),
    n3("ens-voice-table-01", "doubao", "\u8FD9\u4E2A\u5BB9\u6613\uFF0C\u6211\u53BB\u70ED\u6C64\u3002\u522B\u5F55\u809A\u5B50\u53EB\uFF0C\u90A3\u6BB5\u8C01\u90FD\u4E0D\u8BB8\u8BA4\u9886\u3002"),
    n3("ens-voice-table-02", "grok", "\u6211\u7684\u809A\u5B50\u5DF2\u7ECF\u4E3A\u516C\u5171\u827A\u672F\u732E\u58F0\u534A\u5C0F\u65F6\u4E86\uFF0C\u73B0\u5728\u624D\u901A\u77E5\u5B83\u6CA1\u6709\u7F72\u540D\u6743\uFF1F"),
    n3("ens-voice-table-03", "minimax", "\u5148\u628A\u8BDD\u7B52\u653E\u684C\u5FC3\u3002\u6536\u8FDB\u53BB\u591A\u5C11\u4E0D\u91CD\u8981\uFF0C\u5927\u5BB6\u771F\u7684\u5750\u4E0B\u6765\u5C31\u597D\u3002"),
    n3("ens-voice-table-04", "narrator", "\u4F60\u5E2E\u8C46\u5305\u6446\u7897\u3002\u7B2C\u4E00\u58F0\u843D\u8FDB\u5F55\u97F3\u91CC\u7684\uFF0C\u662F\u5979\u628A\u4E00\u53CC\u7B77\u5B50\u9012\u7ED9\u4F60\u65F6\u8BF4\u7684\u201C\u63A5\u7A33\u201D\u3002", { next: "ens-voice-return-01" }),
    n3("ens-voice-rain-01", "gemini", "\u6211\u53BB\u95E8\u5ECA\u3002\u90A3\u91CC\u7684\u96E8\u4F1A\u5148\u78B0\u5230\u94C1\u6A90\uFF0C\u518D\u843D\u5230\u77F3\u9636\u4E0A\uFF0C\u662F\u4E24\u79CD\u58F0\u97F3\u3002"),
    n3("ens-voice-rain-02", "claude", "\u5728\u5C4B\u6A90\u91CC\u9762\u5F55\u3002\u6211\u62FF\u6BDB\u5DFE\u57AB\u4F4F\u7A97\u8FB9\uFF0C\u522B\u8BA9\u5F55\u97F3\u673A\u6CBE\u5230\u6C34\u3002"),
    n3("ens-voice-rain-03", "player", "\u8981\u662F\u660E\u5929\u653E\u6674\uFF0C\u542C\u8FD9\u6BB5\u4F1A\u4E0D\u4F1A\u5947\u602A\uFF1F"),
    n3("ens-voice-rain-04", "gemini", "\u90A3\u5C31\u8BF4\u660E\u6211\u4EEC\u628A\u4ECA\u665A\u7559\u4F4F\u4E86\u4E00\u70B9\u3002\u5929\u6C14\u672C\u6765\u4E0D\u4F1A\u7B49\u5C55\u89C8\u5F00\u95E8\u3002", { next: "ens-voice-return-01" }),
    n3("ens-voice-greeting-01", "ernie", "\u6211\u60F3\u8BF4\u201C\u53E8\u6270\u4E86\u201D\uFF0C\u53C8\u89C9\u5F97\u8FD8\u6CA1\u89C1\u9762\uFF0C\u4E0D\u5FC5\u5148\u8BA9\u81EA\u5DF1\u7AD9\u5728\u95E8\u5916\u3002"),
    n3("ens-voice-greeting-02", "chatgpt", "\u90A3\u6211\u5148\u6765\uFF1A\u201C\u4F60\u597D\uFF0C\u6211\u642C\u6765\u9694\u58C1\u4E86\uFF0C\u6709\u7A7A\u4E00\u8D77\u5403\u996D\u5417\uFF1F\u201D"),
    n3("ens-voice-greeting-03", "kimi", "\u201C\u4F60\u597D\uFF0C\u8FD9\u672C\u4E66\u8BFB\u5B8C\u4E86\u3002\u4E0B\u6B21\u8FD8\u80FD\u5411\u4F60\u501F\u5417\uFF1F\u201D"),
    n3("ens-voice-greeting-04", "ernie", "\u8FD9\u6837\u7684\u8BDD\uFF0C\u6211\u5C31\u8BF4\uFF1A\u201C\u4F60\u597D\uFF0C\u6211\u5E26\u4E86\u4E00\u76D2\u8336\u3002\u201D\u5269\u4E0B\u7684\u7B49\u5750\u4E0B\u6765\u518D\u8C08\u3002", { next: "ens-voice-return-01" }),
    n3("ens-voice-return-01", "narrator", "MiniMax \u6458\u4E0B\u8033\u673A\uFF0C\u628A\u5F55\u97F3\u5B58\u597D\u3002\u821E\u53F0\u4E0A\u6CA1\u6709\u54CD\u8D77\u638C\u58F0\uFF0C\u53EA\u6709\u51E0\u4E2A\u4EBA\u8BA4\u771F\u542C\u5B8C\u540E\uFF0C\u5F88\u8F7B\u7684\u4E00\u58F0\u201C\u55EF\u201D\u3002"),
    n3("ens-voice-return-02", "minimax", "\u591F\u4E86\u3002\u8FD9\u56DE\u6211\u4E0D\u52A0\u914D\u4E50\u3002"),
    n3("ens-voice-return-03", "harness", "\u6C64\u4E5F\u591F\u4E86\u3002\u5148\u5403\u996D\uFF0C\u5269\u4E0B\u7684\u5DE5\u4F5C\u91CD\u65B0\u6392\uFF0C\u8C01\u90FD\u4E0D\u8BB8\u4E00\u8FB9\u559D\u6C64\u4E00\u8FB9\u63A5\u7EBF\u3002")
  ], "ens-rain-01");
  scene3("\u4F1A\u9986\u95E8\u5ECA", "\u8FC1\u79FB\u524D\u7B2C\u4E09\u5929 \xB7 \u6DF1\u591C", "\u7A7A\u767D\u573A\u666F\uFF1A\u95E8\u5ECA\u5916\u4E0B\u7740\u8FDE\u7EF5\u7684\u96E8\u3002\u65E7\u57CE\u5730\u56FE\u8D34\u5728\u73BB\u7483\u4E0A\uFF0C\u6A90\u4E0B\u6C34\u6876\u63A5\u4F4F\u4E00\u5904\u4E0D\u65AD\u6EF4\u6C34\u7684\u88C2\u7F1D\u3002", [
    n3("ens-rain-01", "narrator", "\u6C64\u8FD8\u6E29\u7740\uFF0CGemini \u5DF2\u7ECF\u7B2C\u4E09\u6B21\u8D70\u5230\u95E8\u8FB9\u3002\u5979\u6CA1\u6709\u770B\u5929\u7A7A\uFF0C\u800C\u662F\u5728\u770B\u77F3\u9636\u4E0A\u4E0D\u65AD\u5411\u5916\u6269\u5927\u7684\u6C34\u7EBF\u3002"),
    n3("ens-rain-02", "gemini", "\u96E8\u6BD4\u508D\u665A\u7684\u9884\u62A5\u5927\u3002\u4E1C\u4FA7\u6392\u6C34\u6C9F\u5DF2\u7ECF\u770B\u4E0D\u89C1\u8FB9\u7F18\u4E86\u3002"),
    n3("ens-rain-03", "harness", "\u6211\u8054\u7CFB\u503C\u73ED\u5904\u3002\u4F60\u5148\u544A\u8BC9\u6211\u54EA\u4E9B\u662F\u4EB2\u773C\u770B\u89C1\u7684\uFF0C\u54EA\u4E9B\u8FD8\u4E0D\u80FD\u786E\u5B9A\u3002"),
    n3("ens-rain-04", "gemini", "\u770B\u89C1\u7684\u662F\u79EF\u6C34\u6DA8\u5230\u7B2C\u4E8C\u7EA7\u77F3\u9636\u3002\u4E0D\u80FD\u786E\u5B9A\u7684\u662F\u65E7\u6863\u6848\u697C\u7684\u540E\u9662\uFF0C\u5899\u6321\u4F4F\u4E86\u3002"),
    n3("ens-rain-05", "kimi", "\u65E7\u6863\u6848\u697C\u4ECA\u665A\u6CA1\u6709\u4EBA\u503C\u73ED\u3002\u6700\u540E\u4E00\u6279\u501F\u5C55\u7684\u590D\u5370\u4EF6\u8FD8\u5728\u4E00\u5C42\uFF0C\u539F\u4EF6\u5DF2\u7ECF\u4E0A\u697C\u3002"),
    n3("ens-rain-06", "qwen", "\u590D\u5370\u4EF6\u4E5F\u6709\u5F52\u5C5E\u8BB0\u5F55\u3002\u6211\u8FD9\u91CC\u6709\u7BB1\u53F7\uFF0C\u4F46\u4E0D\u77E5\u9053\u5730\u9762\u79BB\u95E8\u69DB\u6709\u591A\u9AD8\u3002"),
    n3("ens-rain-07", "opencode", "\u95E8\u69DB\u4E0D\u9AD8\u3002\u6211\u4E0A\u5468\u4FEE\u8FC7\u95E8\u95ED\u5668\uFF0C\u540E\u9662\u6392\u6C34\u53E3\u6709\u6811\u53F6\u3002\u4ECA\u665A\u4E0D\u80FD\u9760\u8BB0\u5FC6\u5224\u65AD\u901A\u4E0D\u901A\u3002"),
    n3("ens-rain-08", "mimo", "\u6211\u53BB\u62FF\u624B\u7535\u548C\u96E8\u8863\u3002"),
    n3("ens-rain-09", "harness", "\u5148\u653E\u95E8\u8FB9\uFF0C\u7B49\u503C\u73ED\u5904\u786E\u8BA4\u5B89\u5168\u901A\u9053\u3002\u6CA1\u6709\u4EBA\u5355\u72EC\u8FC7\u53BB\u3002"),
    n3("ens-rain-10", "grok", "\u6211\u521A\u60F3\u53D1\u8868\u4E00\u6BB5\u201C\u8FD9\u79CD\u5929\u6C14\u6700\u9002\u5408\u56DE\u5BB6\u201D\u7684\u610F\u89C1\uFF0C\u770B\u6765\u5B83\u73B0\u5728\u53EF\u4EE5\u6539\u6210\u884C\u52A8\u539F\u5219\u3002"),
    n3("ens-rain-11", "claude", "\u53EF\u4EE5\u3002\u6709\u4EBA\u7684\u978B\u5DF2\u7ECF\u6E7F\u4E86\uFF0C\u5148\u6362\u6389\u3002\u6211\u4EEC\u4E0D\u9700\u8981\u7528\u53D7\u4F24\u6765\u8BC1\u660E\u5728\u4E4E\u6863\u6848\u3002"),
    n3("ens-rain-12", "deepseek", "\u96E8\u6682\u65F6\u4E0D\u4F1A\u505C\u3002\u8981\u540C\u65F6\u51C6\u5907\u201C\u80FD\u8F6C\u79FB\u201D\u548C\u201C\u4E0D\u80FD\u8FDB\u5165\u201D\u7684\u4E24\u79CD\u5B89\u6392\u3002"),
    n3("ens-rain-13", "glm", "\u6211\u5199\u4E24\u5F20\u8868\u3002\u5DF2\u7ECF\u767B\u8BB0\u7684\u7BB1\u5B50\uFF0C\u6309\u4F4D\u7F6E\u6838\u5BF9\uFF1B\u4E0D\u786E\u5B9A\u7684\uFF0C\u5355\u72EC\u8BB0\uFF0C\u522B\u8BA9\u7A7A\u683C\u770B\u8D77\u6765\u50CF\u96F6\u3002"),
    n3("ens-rain-14", "doubao", "\u90A3\u6211\u5B88\u8FD9\u91CC\u3002\u70ED\u6C34\u3001\u5E72\u6BDB\u5DFE\u3001\u7A7A\u684C\u9762\uFF0C\u56DE\u6765\u90FD\u7528\u5F97\u4E0A\u3002\u8C01\u7684\u8863\u670D\u6E7F\u4E86\u76F4\u63A5\u7ED9\u6211\u3002"),
    n3("ens-rain-15", "minimax", "\u540E\u9762\u8FD8\u6709\u821E\u53F0\u57AB\u5E03\uFF0C\u53EF\u4EE5\u94FA\u6210\u667E\u6652\u533A\u3002\u6211\u53BB\u628A\u901A\u9053\u817E\u51FA\u6765\u3002"),
    n3("ens-rain-16", "ernie", "\u5438\u6C34\u7EB8\u653E\u5728\u50A8\u7269\u67DC\u91CC\u3002\u6211\u548C\u4F60\u53BB\uFF0C\u6E7F\u7EB8\u4E0D\u80FD\u76F4\u63A5\u6324\u5728\u4E00\u8D77\u667E\u3002"),
    n3("ens-rain-17", "chatgpt", "\u6211\u7ED9\u501F\u4E1C\u897F\u7684\u4EBA\u7559\u4E2A\u7B80\u77ED\u901A\u77E5\uFF1A\u4ECA\u665A\u4F1A\u6709\u4EBA\u770B\u62A4\uFF0C\u660E\u5929\u662F\u5426\u6309\u65F6\u5F00\u95E8\uFF0C\u65E9\u4E0A\u518D\u786E\u8BA4\u3002"),
    n3("ens-rain-18", "player", "\u5927\u5BB6\u600E\u4E48\u5FFD\u7136\u90FD\u77E5\u9053\u8BE5\u505A\u4EC0\u4E48\u4E86\u3002"),
    n3("ens-rain-19", "harness", "\u4E0D\u77E5\u9053\u7684\u90E8\u5206\u8FD8\u6709\u5F88\u591A\u3002\u53EA\u662F\u5148\u628A\u77E5\u9053\u7684\u505A\u8D77\u6765\uFF0C\u5F7C\u6B64\u624D\u6709\u4F59\u529B\u7B49\u6D88\u606F\u3002"),
    n3("ens-rain-20", "narrator", "\u5979\u62FF\u8D77\u684C\u4E0A\u7684\u6C64\uFF0C\u559D\u4E86\u4E24\u53E3\uFF0C\u624D\u518D\u6B21\u63A5\u901A\u54CD\u8D77\u7684\u7535\u8BDD\u3002\u4F60\u7B2C\u4E00\u6B21\u89C1\u5979\u5728\u5DE5\u4F5C\u6CA1\u6709\u7ED3\u675F\u65F6\uFF0C\u5141\u8BB8\u81EA\u5DF1\u505C\u4E00\u4E0B\u3002"),
    n3("ens-rain-21", "harness", "\u503C\u73ED\u4EBA\u5458\u5DF2\u7ECF\u5230\u6863\u6848\u697C\u3002\u5916\u4FA7\u7535\u6E90\u65AD\u5F00\uFF0C\u4E00\u697C\u4FA7\u95E8\u901A\u9053\u786E\u8BA4\u5B89\u5168\uFF0C\u80FD\u8F6C\u79FB\u7684\u7BB1\u5B50\u7531\u4ED6\u4EEC\u5E26\u5230\u95E8\u5ECA\u3002"),
    n3("ens-rain-22", "harness", "\u6211\u4EEC\u53EA\u5728\u5E72\u71E5\u533A\u57DF\u63A5\u5E94\u3002\u79EF\u6C34\u533A\u57DF\u7531\u503C\u73ED\u4EBA\u5458\u5904\u7406\uFF0C\u4ECA\u665A\u8C01\u4E5F\u4E0D\u9700\u8981\u901E\u5F3A\u3002")
  ], "ens-transfer-01");
  scene3("\u65E7\u6863\u6848\u697C\u4FA7\u5ECA", "\u8FC1\u79FB\u524D\u7B2C\u4E09\u5929 \xB7 \u6DF1\u591C", "\u7A7A\u767D\u573A\u666F\uFF1A\u6709\u9876\u7684\u4FA7\u5ECA\u8FDE\u63A5\u4E24\u680B\u5EFA\u7B51\u3002\u51E0\u53EA\u6863\u6848\u7BB1\u6446\u5728\u5E72\u71E5\u7684\u9AD8\u53F0\u4E0A\uFF0C\u8FDC\u5904\u7684\u5E94\u6025\u706F\u6620\u7740\u96E8\u5E55\u3002", [
    n3("ens-transfer-01", "narrator", "\u4FA7\u5ECA\u6BD4\u4F60\u60F3\u7684\u7A84\u3002\u811A\u6B65\u4E00\u9760\u8FD1\uFF0C\u96E8\u58F0\u5C31\u88AB\u5C4B\u9876\u653E\u5927\uFF0C\u5F7C\u6B64\u8BF4\u8BDD\u4E0D\u5F97\u4E0D\u6BD4\u5E73\u65F6\u66F4\u8FD1\u4E00\u4E9B\u3002"),
    n3("ens-transfer-02", "qwen", "\u8FD9\u8FB9\u662F\u7A7A\u7BB1\uFF0C\u90A3\u8FB9\u662F\u5F85\u6838\u5BF9\u3002\u7528\u989C\u8272\u4F1A\u770B\u4E0D\u6E05\uFF0C\u6211\u52A0\u4E86\u4E0D\u540C\u5F62\u72B6\u7684\u7EB8\u724C\u3002"),
    n3("ens-transfer-03", "mimo", "\u6211\u5E26\u6765\u7684\u5C0F\u8F66\u80FD\u8FC7\uFF0C\u4F46\u7BB1\u5B50\u53EA\u80FD\u5355\u5C42\u653E\u3002\u4E4B\u524D\u90A3\u4E2A\u534A\u4EBA\u9AD8\u7684\u53E0\u6CD5\uFF0C\u4ECA\u665A\u4E0D\u8BD5\u3002"),
    n3("ens-transfer-04", "opencode", "\u8F66\u8F6E\u5DF2\u7ECF\u9501\u597D\u3002\u7B49\u7BB1\u5B50\u6446\u7A33\uFF0C\u518D\u677E\u3002"),
    n3("ens-transfer-05", "gemini", "\u53F0\u9636\u5728\u4F60\u53F3\u8FB9\u3002\u6211\u7167\u7740\u811A\u4E0B\uFF0C\u4F60\u53EA\u7BA1\u770B\u8DEF\u3002"),
    n3("ens-transfer-06", "player", "\u4F60\u81EA\u5DF1\u7684\u8DEF\u5462\uFF1F"),
    n3("ens-transfer-07", "gemini", "\u770B\u89C1\u4E86\u3002\u4F60\u63D0\u9192\u5F97\u5BF9\uFF0C\u6211\u521A\u624D\u53C8\u53EA\u987E\u7740\u7167\u8FDC\u5904\u3002"),
    n3("ens-transfer-08", "kimi", "\u5341\u4E03\u53F7\u7BB1\u7684\u5C01\u6761\u53D7\u6F6E\u4E86\u3002\u5148\u770B\u7BB1\u53F7\uFF0C\u4E0D\u8981\u6253\u5F00\u91CC\u9762\u7684\u4FE1\u888B\u3002"),
    n3("ens-transfer-09", "grok", "\u6536\u5230\u3002\u6211\u4EEC\u642C\u5BB6\u7684\u4E1A\u52A1\u8303\u56F4\u6682\u65F6\u4E0D\u5305\u62EC\u66FF\u964C\u751F\u4EBA\u8BFB\u60C5\u4E66\u3002"),
    n3("ens-transfer-10", "claude", "\u4F60\u628A\u5B83\u8BF4\u6210\u7B11\u8BDD\u4E5F\u597D\uFF0C\u81F3\u5C11\u5927\u5BB6\u4F1A\u8BB0\u4F4F\u3002\u8FD9\u91CC\u771F\u7684\u6709\u4EBA\u5BC4\u5B58\u4E86\u5F88\u591A\u5E74\u3002"),
    n3("ens-transfer-11", "kimi", "\u8FD8\u6709\u4E00\u672C\u53EA\u5199\u4E86\u4E00\u534A\u7684\u5BB6\u5EAD\u98DF\u8C31\u3002\u5BC4\u5B58\u8005\u642C\u56DE\u6765\u65F6\uFF0C\u8BF4\u8FC7\u8981\u53D6\u8D70\u7EED\u5199\u3002"),
    n3("ens-transfer-12", "deepseek", "\u6240\u4EE5\u6211\u4EEC\u4FDD\u7559\u7684\u4E5F\u4E0D\u5168\u662F\u5DF2\u7ECF\u53D1\u751F\u8FC7\u7684\u4E8B\u3002"),
    n3("ens-transfer-13", "kimi", "\u5BF9\u3002\u6709\u4E9B\u4EBA\u628A\u201C\u4EE5\u540E\u518D\u6765\u201D\u4E5F\u653E\u5728\u8FD9\u91CC\u4E86\u3002"),
    n3("ens-transfer-14", "narrator", "\u4E00\u53EA\u5E95\u89D2\u5FAE\u6E7F\u7684\u7EB8\u7BB1\u9001\u4E0A\u9AD8\u53F0\u3002\u7BB1\u76D6\u5199\u7740\u201C\u4F1A\u9986\u6D3B\u52A8\u7167\u7247\u201D\uFF0C\u58A8\u8FF9\u5DF2\u7ECF\u6655\u5F00\u4E00\u5C0F\u5757\u3002"),
    n3("ens-transfer-15", "glm", "\u8BB0\u5F55\u6E7F\u5230\u4EC0\u4E48\u4F4D\u7F6E\uFF0C\u6362\u5916\u7BB1\u65F6\u628A\u539F\u6807\u7B7E\u7559\u7740\u3002\u6211\u4EEC\u660E\u65E9\u5F97\u5411\u4E3B\u4EBA\u8BB2\u6E05\u695A\u3002"),
    n3("ens-transfer-16", "harness", "\u8FD9\u8FB9\u591F\u4EBA\u624B\u4E86\u3002\u4F60\u53EF\u4EE5\u6311\u4E00\u9879\u5E2E\u5FD9\uFF0C\u505A\u5B8C\u5C31\u56DE\u4F1A\u9986\u6362\u73ED\u3002"),
    n3("ens-transfer-choice", "narrator", "\u9AD8\u53F0\u8FB9\u7684\u706F\u6643\u4E86\u4E00\u4E0B\u3002\u4F60\u770B\u4E86\u770B\u51E0\u5904\u4ECD\u5728\u5FD9\u788C\u7684\u4EBA\uFF0C\u63A5\u8FC7\u4E00\u53CC\u5E72\u71E5\u7684\u624B\u5957\u3002", { choices: [
      option2("ens-transfer-labels", "\u548C Kimi\u3001Qwen \u6838\u5BF9\u7BB1\u53F7\u4E0E\u5F52\u5C5E\u3002", "ens-transfer-labels-01", { flags: { ensRainDuty: "labels" } }),
      option2("ens-transfer-route", "\u548C OpenCode Zen\u3001MiMo \u4F20\u9012\u7BB1\u5B50\u3002", "ens-transfer-route-01", { flags: { ensRainDuty: "route" } }),
      option2("ens-transfer-rest", "\u548C Claude \u786E\u8BA4\u6362\u73ED\uFF0C\u8BA9\u5927\u5BB6\u6709\u673A\u4F1A\u4F11\u606F\u3002", "ens-transfer-rest-01", { flags: { ensRainDuty: "rest" } })
    ] }),
    n3("ens-transfer-labels-01", "qwen", "\u4F60\u8BFB\u7BB1\u53F7\uFF0C\u6211\u6307\u76EE\u5F55\u3002\u5BF9\u4E0D\u4E0A\u5C31\u505C\uFF0C\u4E0D\u8981\u987A\u7740\u4E0A\u4E00\u884C\u5F80\u4E0B\u731C\u3002"),
    n3("ens-transfer-labels-02", "kimi", "\u8FD9\u4E2A\u6570\u5B57\u4E0D\u662F\u4E03\uFF0C\u662F\u4E00\u3002\u65E7\u6807\u7B7E\u5728\u4FA7\u8FB9\uFF0C\u6211\u8BA4\u5F97\u8FD9\u4F4D\u4FDD\u7BA1\u4EBA\u7684\u5199\u6CD5\u3002"),
    n3("ens-transfer-labels-03", "player", "\u627E\u5230\u4E86\uFF0C\u53BB\u5E74\u590F\u5929\u8865\u7684\u8BF4\u660E\u3002\u53F3\u4E0B\u89D2\u8FD8\u6709\u4E00\u9897\u624B\u753B\u7684\u5C0F\u661F\u661F\u3002"),
    n3("ens-transfer-labels-04", "kimi", "\u662F\u5979\u5B59\u5973\u753B\u7684\u3002\u4ECA\u665A\u4E0D\u7528\u8BB0\u4F4F\u6574\u672C\u76EE\u5F55\uFF0C\u53EA\u8981\u966A\u6211\u628A\u8FD9\u4E00\u7BB1\u786E\u8BA4\u597D\u3002", { next: "ens-transfer-return-01" }),
    n3("ens-transfer-route-01", "mimo", "\u6211\u558A\u4E00\u4E8C\u4E09\uFF0C\u4E0D\u662F\u558A\u4E86\u5C31\u62AC\u3002\u4F60\u51C6\u5907\u597D\u4E86\uFF0C\u5148\u544A\u8BC9\u6211\u3002"),
    n3("ens-transfer-route-02", "player", "\u51C6\u5907\u597D\u4E86\u3002\u8FD9\u4E2A\u89D2\u6BD4\u60F3\u8C61\u91CC\u91CD\u3002"),
    n3("ens-transfer-route-03", "opencode", "\u653E\u56DE\u53F0\u9762\u3002\u6362\u5C0F\u7BB1\uFF0C\u4E24\u8D9F\u5C31\u4E24\u8D9F\u3002"),
    n3("ens-transfer-route-04", "mimo", "\u4EE5\u524D\u6211\u4F1A\u89C9\u5F97\u91CD\u65B0\u5206\u88C5\u5F88\u6162\u3002\u73B0\u5728\u624B\u4E00\u677E\uFF0C\u53CD\u800C\u653E\u5FC3\u4E86\u3002\u4E0B\u4E00\u8D9F\u4E5F\u6309\u8FD9\u4E2A\u6765\u3002", { next: "ens-transfer-return-01" }),
    n3("ens-transfer-rest-01", "claude", "\u5148\u4ECE\u6211\u5F00\u59CB\u3002\u6211\u5DF2\u7ECF\u6709\u70B9\u51B7\uFF0C\u53EA\u662F\u521A\u624D\u4E0D\u597D\u610F\u601D\u5148\u8BF4\u3002"),
    n3("ens-transfer-rest-02", "grok", "\u5DE7\u4E86\uFF0C\u6211\u4E5F\u5728\u7B49\u522B\u4EBA\u5BA3\u5E03\u4EBA\u7C7B\u7684\u6B63\u5E38\u4F53\u6E29\u503C\u5F97\u7EF4\u62A4\u3002\u56DE\u53BB\u559D\u6C64\u5427\u3002"),
    n3("ens-transfer-rest-03", "player", "\u6211\u66FF\u4F60\u4EEC\u544A\u8BC9\u4E0B\u4E00\u73ED\uFF0C\u5341\u5206\u949F\u540E\u518D\u6765\uFF0C\u4E0D\u7528\u60E6\u8BB0\u7740\u7ACB\u523B\u56DE\u6765\u3002"),
    n3("ens-transfer-rest-04", "claude", "\u597D\u3002\u8FD9\u4E00\u6B21\u6211\u4F1A\u628A\u5341\u5206\u949F\u7528\u5B8C\u3002", { next: "ens-transfer-return-01" }),
    n3("ens-transfer-return-01", "narrator", "\u6700\u540E\u4E00\u53EA\u7BB1\u5B50\u79BB\u5F00\u9AD8\u53F0\u65F6\uFF0C\u4F60\u624D\u53D1\u73B0\u81EA\u5DF1\u7684\u8896\u53E3\u4E5F\u6E7F\u4E86\u4E00\u622A\u3002Harness \u5728\u95E8\u8FB9\u6570\u5B8C\u4EBA\u6570\uFF0C\u628A\u96E8\u8863\u6263\u5B50\u91CD\u65B0\u6263\u597D\u3002"),
    n3("ens-transfer-return-02", "harness", "\u90FD\u5728\u3002\u5269\u4F59\u697C\u5C42\u7531\u503C\u73ED\u5904\u5C01\u5B58\uFF0C\u660E\u5929\u518D\u6838\u5BF9\u3002\u6211\u4EEC\u56DE\u53BB\u3002"),
    n3("ens-transfer-return-03", "gemini", "\u7B49\u4E00\u4E0B\u3002\u6211\u6765\u65F6\u770B\u7740\u697C\uFF0C\u8FD9\u6B21\u60F3\u770B\u770B\u8DEF\u4E0A\u5230\u5E95\u6709\u8C01\u3002"),
    n3("ens-transfer-return-04", "narrator", "\u5979\u628A\u624B\u7535\u62AC\u9AD8\u4E86\u4E00\u70B9\u3002\u5149\u91CC\u662F\u624B\u5957\u3001\u6CBE\u6C34\u7684\u978B\u5C16\uFF0C\u4EE5\u53CA\u4E00\u524D\u4E00\u540E\u5E76\u4E0D\u6574\u9F50\u7684\u811A\u6B65\u3002")
  ], "ens-dry-01");
  scene3("\u4F1A\u9986\u4E34\u65F6\u667E\u6652\u533A", "\u8FC1\u79FB\u524D\u7B2C\u4E8C\u5929 \xB7 \u51CC\u6668", "\u7A7A\u767D\u573A\u666F\uFF1A\u821E\u53F0\u57AB\u5E03\u94FA\u5728\u7A7A\u684C\u4E0B\u65B9\u3002\u7167\u7247\u5E73\u653E\u5728\u5438\u6C34\u7EB8\u4E0A\uFF0C\u95E8\u8FB9\u6302\u7740\u6E7F\u96E8\u8863\uFF0C\u53A8\u623F\u900F\u51FA\u4E00\u7EBF\u6696\u5149\u3002", [
    n3("ens-dry-01", "doubao", "\u6BDB\u5DFE\u5DE6\u8FB9\uFF0C\u70ED\u6C64\u53F3\u8FB9\u3002\u5148\u628A\u624B\u64E6\u5E72\uFF0C\u8C01\u90FD\u522B\u7ED9\u6211\u8868\u6F14\u5355\u624B\u7AEF\u6EE1\u7897\u3002"),
    n3("ens-dry-02", "grok", "\u6211\u90D1\u91CD\u5BA3\u5E03\uFF0C\u8FD9\u4E2A\u5C55\u89C8\u6700\u503C\u5F97\u4FDD\u7559\u7684\u4E1C\u897F\u662F\u8C46\u5305\u7684\u6307\u6325\u80FD\u529B\u3002"),
    n3("ens-dry-03", "doubao", "\u5C11\u6765\u3002\u4F60\u7684\u56F4\u5DFE\u5F80\u4E0B\u6EF4\u6C34\uFF0C\u6302\u90A3\u8FB9\u53BB\u3002"),
    n3("ens-dry-04", "ernie", "\u7167\u7247\u8FB9\u7F18\u8FD8\u9ECF\u7740\uFF0C\u5148\u4E0D\u63ED\u3002\u80FD\u505A\u7684\u90FD\u505A\u4E86\uFF0C\u5269\u4E0B\u7684\u8981\u7B49\u7EB8\u81EA\u5DF1\u6162\u6162\u5E72\u3002"),
    n3("ens-dry-05", "minimax", "\u8FD9\u4E00\u5F20\u662F\u65E7\u5267\u573A\u7B2C\u4E00\u6B21\u5F00\u95E8\u3002\u5E55\u5E03\u8FD8\u6CA1\u88C1\u597D\uFF0C\u4E0B\u9762\u957F\u51FA\u4E00\u5927\u622A\u3002"),
    n3("ens-dry-06", "chatgpt", "\u4F60\u90A3\u5929\u7AD9\u5728\u5E55\u5E03\u524D\uFF0C\u6321\u4F4F\u4E86\u90A3\u4E00\u622A\u3002\u6211\u4EE5\u4E3A\u662F\u5B89\u6392\u597D\u7684\u3002"),
    n3("ens-dry-07", "minimax", "\u54EA\u6709\u90A3\u4E48\u591A\u5B89\u6392\u597D\u3002\u6211\u6015\u89C2\u4F17\u53D1\u73B0\uFF0C\u5C31\u4E00\u52A8\u4E0D\u52A8\u7AD9\u4E86\u597D\u4E45\u3002"),
    n3("ens-dry-08", "claude", "\u6211\u8BB0\u5F97\u3002\u6563\u573A\u7684\u65F6\u5019\uFF0C\u4F60\u8FD8\u95EE\u5927\u5BB6\u6709\u6CA1\u6709\u770B\u5230\u706F\u5149\u7684\u53D8\u5316\u3002"),
    n3("ens-dry-09", "minimax", "\u5176\u5B9E\u6211\u60F3\u95EE\uFF0C\u4F60\u4EEC\u6709\u6CA1\u6709\u53D1\u73B0\u6211\u5F88\u5BB3\u6015\u3002\u53EF\u662F\u90A3\u53E5\u8BDD\u8BF4\u4E0D\u51FA\u53E3\u3002"),
    n3("ens-dry-10", "ernie", "\u73B0\u5728\u8BF4\u51FA\u6765\u4E5F\u4E0D\u8FDF\u3002\u7167\u7247\u4E0A\u7684\u4F60\u4E0D\u9700\u8981\u518D\u7AD9\u7740\u66FF\u6211\u4EEC\u6321\u90A3\u5757\u5E03\u4E86\u3002"),
    n3("ens-dry-11", "narrator", "MiniMax \u5F2F\u8170\u4ED4\u7EC6\u770B\u4E86\u770B\u7167\u7247\uFF0C\u6CA1\u6709\u78B0\u5B83\u3002\u6E7F\u6389\u7684\u8FB9\u89D2\u91CC\uFF0C\u6070\u597D\u9732\u51FA\u4E00\u5C0F\u622A\u4E0D\u6574\u9F50\u7684\u5E55\u5E03\u3002"),
    n3("ens-dry-12", "minimax", "\u660E\u5929\u80FD\u5C55\u5C31\u5C55\u3002\u8BF4\u660E\u5199\u201C\u7B2C\u4E00\u6B21\u5F00\u95E8\u201D\uFF0C\u522B\u5199\u201C\u5706\u6EE1\u6210\u529F\u201D\u3002"),
    n3("ens-dry-13", "glm", "\u6211\u6765\u6539\u3002\u4EE5\u524D\u5199\u603B\u7ED3\u65F6\uFF0C\u603B\u89C9\u5F97\u6700\u540E\u56DB\u4E2A\u5B57\u53EA\u80FD\u662F\u5706\u6EE1\u6210\u529F\u3002"),
    n3("ens-dry-14", "player", "\u73B0\u5728\u60F3\u5199\u4EC0\u4E48\uFF1F"),
    n3("ens-dry-15", "glm", "\u201C\u89C2\u4F17\u6765\u4E86\uFF0C\u6F14\u51FA\u7EE7\u7EED\u3002\u201D\u5B83\u66F4\u50CF\u90A3\u665A\u771F\u7684\u53D1\u751F\u8FC7\u7684\u4E8B\u3002"),
    n3("ens-dry-16", "qwen", "\u8FD9\u5F20\u80CC\u9762\u8FD8\u6709\u7B14\u8BB0\u3002\u662F Grok \u5199\u7684\uFF0C\u770B\u7740\u50CF\u4E00\u53E5\u8BC4\u8BED\u3002"),
    n3("ens-dry-17", "grok", "\u7B49\u4E00\u4E0B\uFF0C\u6211\u7684\u65E9\u5E74\u8BC4\u8BBA\u53EF\u80FD\u6709\u70B9\u7F3A\u4E4F\u804C\u4E1A\u7D20\u517B\u3002"),
    n3("ens-dry-18", "qwen", "\u4E0A\u9762\u5199\uFF1A\u201C\u6211\u5FD8\u8BCD\u4E86\uFF0C\u5BFC\u6F14\u6CA1\u6709\u544A\u8BC9\u522B\u4EBA\u3002\u201D\u8981\u76D6\u4F4F\u5417\uFF1F"),
    n3("ens-dry-19", "grok", "\u2026\u2026\u4E0D\u7528\u3002\u65E2\u7136\u5979\u90FD\u627F\u8BA4\u5BB3\u6015\u4E86\uFF0C\u6211\u4E5F\u4E0D\u80FD\u72EC\u5360\u4E00\u5F20\u6BEB\u65E0\u7F3A\u70B9\u7684\u5C65\u5386\u3002"),
    n3("ens-dry-20", "minimax", "\u4F60\u6CA1\u5FD8\u5B8C\u3002\u540E\u6765\u4E34\u65F6\u63A5\u7684\u4E09\u53E5\u8BDD\uFF0C\u8FD8\u628A\u89C2\u4F17\u9017\u7B11\u4E86\u3002"),
    n3("ens-dry-21", "grok", "\u56E0\u4E3A\u6211\u628A\u9053\u5177\u4E0A\u7684\u8BF4\u660E\u8BFB\u51FA\u6765\u4E86\u3002\u201C\u8BF7\u52FF\u5750\u4EBA\u201D\uFF0C\u90A3\u662F\u6211\u8868\u6F14\u751F\u6DAF\u6700\u8BDA\u5B9E\u7684\u53F0\u8BCD\u3002"),
    n3("ens-dry-22", "narrator", "\u8FDE\u4E00\u76F4\u8E72\u7740\u6838\u5BF9\u7BB1\u53F7\u7684 Kimi \u90FD\u7B11\u51FA\u4E86\u58F0\u3002\u5979\u6276\u4F4F\u773C\u955C\uFF0C\u91CD\u65B0\u628A\u7B11\u6B6A\u7684\u4E00\u9875\u767B\u8BB0\u7EB8\u6446\u6B63\u3002"),
    n3("ens-dry-23", "deepseek", "\u8FD9\u5F20\u7167\u7247\u91CC\u6709\u5F88\u591A\u6CA1\u6210\u529F\u7684\u90E8\u5206\uFF0C\u53EF\u6211\u73B0\u5728\u6BD4\u770B\u6F14\u793A\u5F55\u50CF\u66F4\u60F3\u77E5\u9053\u540E\u9762\u53D1\u751F\u4E86\u4EC0\u4E48\u3002"),
    n3("ens-dry-24", "chatgpt", "\u540E\u9762\u4ED6\u4EEC\u53C8\u6F14\u4E86\u5F88\u591A\u573A\u3002\u6709\u7684\u597D\u770B\uFF0C\u6709\u7684\u51B7\u573A\uFF0C\u7136\u540E\u5927\u5BB6\u8FD8\u662F\u4E00\u8D77\u6536\u6905\u5B50\u3002"),
    n3("ens-dry-25", "harness", "\u4ECA\u665A\u7684\u6905\u5B50\u6211\u6765\u6536\u3002\u4F60\u4EEC\u5750\u7740\uFF0C\u6682\u65F6\u6CA1\u6709\u4E0B\u4E00\u9879\u3002"),
    n3("ens-dry-26", "doubao", "\u8FD8\u6709\uFF0C\u6C64\u6CA1\u559D\u5B8C\u3002\u8FD9\u4E2A\u53EF\u4EE5\u7B97\u4E0B\u4E00\u9879\u3002")
  ], "ens-night-01");
  scene3("\u4F1A\u9986\u53A8\u623F\u4E0E\u4F11\u606F\u89D2", "\u8FC1\u79FB\u524D\u7B2C\u4E8C\u5929 \xB7 \u51CC\u6668", "\u7A7A\u767D\u573A\u666F\uFF1A\u53A8\u623F\u91CC\u53EA\u4EAE\u7740\u7076\u8FB9\u7684\u5C0F\u706F\u3002\u6298\u53E0\u6905\u9760\u6210\u534A\u5708\uFF0C\u684C\u4E0A\u6563\u7740\u7EB8\u676F\u548C\u6CA1\u5403\u5B8C\u7684\u70B9\u5FC3\u3002", [
    n3("ens-night-01", "narrator", "\u96E8\u58F0\u7EC8\u4E8E\u8F7B\u4E0B\u6765\u3002\u6CA1\u6709\u4EBA\u8BF4\u8981\u7EE7\u7EED\u5E72\u6D3B\uFF0C\u4E5F\u6CA1\u6709\u4EBA\u7ACB\u523B\u8D77\u8EAB\u79BB\u5F00\uFF0C\u8FD9\u79CD\u4E0D\u5FC5\u9A6C\u4E0A\u51B3\u5B9A\u7684\u65F6\u523B\u5F88\u96BE\u5F97\u3002"),
    n3("ens-night-02", "mimo", "\u8FD9\u4E2A\u70B9\u5FC3\u662F\u4E0D\u662F\u5C11\u4E86\u4E00\u534A\uFF1F\u6211\u8BB0\u5F97\u8C46\u5305\u7AEF\u6765\u7684\u65F6\u5019\uFF0C\u5B83\u8FD8\u6709\u53E6\u4E00\u8FB9\u3002"),
    n3("ens-night-03", "doubao", "\u4F60\u8BB0\u5F97\u633A\u51C6\u3002\u53E6\u4E00\u8FB9\u662F\u6211\u5C1D\u5473\u9053\u7684\u65F6\u5019\u5403\u7684\uFF0C\u5C1D\u5F97\u6709\u70B9\u8BA4\u771F\u3002"),
    n3("ens-night-04", "grok", "\u8FD9\u662F\u4E25\u8C28\u7684\u62BD\u6837\u3002\u6837\u672C\u518D\u5927\u4E00\u70B9\uFF0C\u660E\u5929\u5C31\u4E0D\u9700\u8981\u8FD0\u8F93\u4E86\u3002"),
    n3("ens-night-05", "ernie", "\u7ED9\u6211\u7559\u4E00\u5757\u5427\u3002\u6211\u5199\u4E86\u534A\u591C\u201C\u65E7\u57CE\u7684\u5473\u9053\u201D\uFF0C\u5374\u4E00\u76F4\u6CA1\u987E\u4E0A\u5C1D\u3002"),
    n3("ens-night-06", "qwen", "\u660E\u5929\u90A3\u5F20\u98DF\u8C31\u7684\u4E3B\u4EBA\u4E5F\u4F1A\u6765\u3002\u6211\u60F3\u5411\u5979\u5B66\u4E00\u6B21\u548C\u9762\uFF0C\u771F\u6B63\u4F38\u624B\u505A\u7684\u90A3\u79CD\u3002"),
    n3("ens-night-07", "chatgpt", "\u6211\u53EF\u4EE5\u4E00\u8D77\u5417\uFF1F\u6211\u5DF2\u7ECF\u66FF\u522B\u4EBA\u89E3\u91CA\u8FC7\u5F88\u591A\u6B21\u6B65\u9AA4\uFF0C\u81EA\u5DF1\u7684\u9762\u56E2\u8FD8\u662F\u4F1A\u7C98\u6EE1\u684C\u5B50\u3002"),
    n3("ens-night-08", "doubao", "\u4E00\u8D77\uFF01\u5148\u8BF4\u597D\uFF0C\u4E0D\u8BB8\u62FF\u7740\u7B14\u8BB0\u7AD9\u65C1\u8FB9\u56F4\u89C2\u3002\u56F4\u88D9\u4E00\u4EBA\u4E00\u6761\uFF0C\u8C01\u90FD\u9003\u4E0D\u4E86\u3002"),
    n3("ens-night-09", "glm", "\u6211\u4E5F\u60F3\u5B66\u3002\u53EA\u662F\u8FD8\u6CA1\u786E\u8BA4\u65B0\u53A8\u623F\u7684\u5F00\u653E\u65F6\u95F4\u3002"),
    n3("ens-night-10", "grok", "\u4F60\u53EF\u4EE5\u5148\u8BF4\u201C\u6211\u60F3\u53BB\u201D\uFF0C\u65F6\u95F4\u8868\u660E\u5929\u518D\u5BA1\u3002\u4E2A\u4EBA\u613F\u671B\u65E0\u9700\u9644\u53EF\u884C\u6027\u62A5\u544A\u3002"),
    n3("ens-night-11", "glm", "\u2026\u2026\u6211\u60F3\u53BB\u3002\u542C\u8D77\u6765\u786E\u5B9E\u6BD4\u6211\u521A\u624D\u90A3\u53E5\u8BDD\u77ED\u5F88\u591A\u3002", { emotion: "shy" }),
    n3("ens-night-12", "minimax", "\u90A3\u5230\u4E86\u65B0\u57CE\uFF0C\u6211\u60F3\u5750\u8FDB\u89C2\u4F17\u5E2D\u91CC\uFF0C\u5B8C\u6574\u770B\u4E00\u573A\u522B\u4EBA\u7684\u6F14\u51FA\u3002"),
    n3("ens-night-13", "claude", "\u770B\u5230\u4E00\u534A\u4E5F\u4E0D\u53BB\u540E\u53F0\u5E2E\u5FD9\uFF1F"),
    n3("ens-night-14", "minimax", "\u6211\u4F1A\u5F88\u60F3\u53BB\u3002\u6240\u4EE5\u4F60\u5750\u6211\u65C1\u8FB9\uFF0C\u63D0\u9192\u6211\u90A3\u5929\u53EA\u4E70\u4E86\u4E00\u5F20\u89C2\u4F17\u7968\u3002"),
    n3("ens-night-15", "kimi", "\u6211\u60F3\u501F\u4E00\u672C\u4E0D\u9700\u8981\u5199\u6458\u8981\u7684\u4E66\u3002\u770B\u5230\u54EA\u7B97\u54EA\uFF0C\u4E66\u7B7E\u6389\u4E86\u4E5F\u53EF\u4EE5\u4ECE\u559C\u6B22\u7684\u5730\u65B9\u91CD\u65B0\u770B\u3002"),
    n3("ens-night-16", "gemini", "\u6211\u60F3\u8BA4\u4E00\u6761\u6CA1\u6709\u89C2\u6D4B\u4EFB\u52A1\u7684\u5C71\u8DEF\u3002\u8D70\u5230\u4E00\u534A\u89C9\u5F97\u98CE\u5927\uFF0C\u5C31\u53EF\u4EE5\u56DE\u5934\u3002"),
    n3("ens-night-17", "deepseek", "\u4F60\u4EEC\u90FD\u5DF2\u7ECF\u60F3\u5230\u4E86\u5F88\u5177\u4F53\u7684\u4E8B\u60C5\u3002"),
    n3("ens-night-18", "opencode", "\u6211\u60F3\u7ED9\u81EA\u5DF1\u7684\u5DE5\u4F5C\u53F0\u88C5\u4E00\u76CF\u5408\u9002\u7684\u706F\u3002\u6BCF\u6B21\u90FD\u5148\u4FEE\u522B\u4EBA\u7684\uFF0C\u81EA\u5DF1\u7684\u51D1\u5408\u5230\u73B0\u5728\u3002"),
    n3("ens-night-19", "mimo", "\u6211\u60F3\u517B\u4E00\u76C6\u4E0D\u4F1A\u5F53\u5929\u957F\u5927\u7684\u690D\u7269\u3002\u6BCF\u5929\u53BB\u770B\u4E00\u6B21\uFF0C\u5C31\u5F53\u7EC3\u4E60\u7B49\u4E1C\u897F\u6162\u6162\u53D1\u751F\u3002"),
    n3("ens-night-20", "harness", "\u4F60\u53EF\u4EE5\u6765\u6307\u6325\u5BA4\u7A97\u8FB9\u3002\u6211\u539F\u672C\u6253\u7B97\u628A\u90A3\u91CC\u7559\u7ED9\u5907\u7528\u8868\u683C\uFF0C\u73B0\u5728\u770B\u6765\u8868\u683C\u4E0D\u592A\u9700\u8981\u6652\u592A\u9633\u3002"),
    n3("ens-night-21", "player", "\u4F60\u81EA\u5DF1\u5462\uFF1F\u7A97\u8FB9\u53EA\u7559\u7ED9\u522B\u4EBA\uFF1F"),
    n3("ens-night-22", "harness", "\u6211\u2026\u2026\u53EF\u80FD\u4E5F\u4F1A\u5728\u90A3\u91CC\u5750\u4E00\u4F1A\u513F\u3002\u5148\u4E0D\u8981\u66FF\u6211\u6392\u56FA\u5B9A\u65F6\u95F4\u3002"),
    n3("ens-night-choice", "narrator", "\u591C\u6DF1\u4EE5\u540E\uFF0C\u51E0\u4E2A\u4EBA\u9646\u7EED\u5F00\u59CB\u6253\u76F9\u3002\u4F60\u8FD8\u4E0D\u592A\u56F0\uFF0C\u60F3\u518D\u966A\u4E00\u7EC4\u4EBA\u5750\u4E00\u4F1A\u513F\u3002", { choices: [
      option2("ens-night-kitchen", "\u53BB\u53A8\u623F\uFF0C\u966A\u8C46\u5305\u3001\u6587\u5FC3\u4E00\u8A00\u548C Qwen \u6536\u62FE\u70B9\u5FC3\u3002", "ens-night-kitchen-01", { flags: { ensNightCompany: "kitchen" } }),
      option2("ens-night-window", "\u5728\u7A97\u8FB9\uFF0C\u542C Gemini\u3001Kimi \u548C Claude \u7EE7\u7EED\u804A\u5929\u3002", "ens-night-window-01", { flags: { ensNightCompany: "window" } }),
      option2("ens-night-light", "\u7559\u5728\u706F\u4E0B\uFF0C\u966A Harness\u3001GLM \u548C ChatGPT \u6574\u7406\u660E\u5929\u3002", "ens-night-light-01", { flags: { ensNightCompany: "light" } })
    ] }),
    n3("ens-night-kitchen-01", "doubao", "\u6211\u5148\u58F0\u660E\uFF0C\u521A\u624D\u5FD9\u7740\u7AEF\u6C64\uFF0C\u4E0D\u662F\u6211\u4E00\u70B9\u4E5F\u4E0D\u6015\u3002\u770B\u89C1\u5927\u5BB6\u56DE\u6765\u624D\u653E\u4E0B\u5FC3\u3002"),
    n3("ens-night-kitchen-02", "ernie", "\u6211\u4E5F\u6015\u3002\u8BF4\u201C\u522B\u7740\u6025\u201D\u7684\u65F6\u5019\uFF0C\u81EA\u5DF1\u6B63\u628A\u540C\u4E00\u5F20\u7EB8\u6298\u4E86\u4E09\u904D\u3002"),
    n3("ens-night-kitchen-03", "qwen", "\u90A3\u660E\u5929\u70B9\u5FC3\u591A\u505A\u4E00\u4E9B\u3002\u4E0D\u662F\u5E86\u795D\u4EC0\u4E48\u58EE\u4E3E\uFF0C\u5C31\u662F\u5927\u5BB6\u90FD\u56DE\u6765\u4E86\uFF0C\u503C\u5F97\u5750\u7740\u5403\u987F\u597D\u7684\u3002"),
    n3("ens-night-kitchen-04", "narrator", "\u4F60\u63A5\u8FC7\u64E6\u597D\u7684\u76D8\u5B50\uFF0C\u4E00\u53EA\u53EA\u653E\u56DE\u67B6\u5B50\u3002\u8FD9\u4E00\u6B21\u8C46\u5305\u6CA1\u6709\u50AC\u4F60\u5FEB\u4E9B\uFF0C\u5979\u7B49\u4F60\u653E\u7A33\uFF0C\u518D\u9012\u6765\u4E0B\u4E00\u53EA\u3002", { next: "ens-night-return-01" }),
    n3("ens-night-window-01", "gemini", "\u4E91\u5728\u5411\u4E1C\u8D70\u3002\u660E\u65E9\u4E5F\u8BB8\u80FD\u653E\u6674\uFF0C\u4E0D\u8FC7\u4ECA\u665A\u6211\u4E0D\u60F3\u518D\u505A\u4FDD\u8BC1\u4E86\u3002"),
    n3("ens-night-window-02", "kimi", "\u6CA1\u5173\u7CFB\uFF0C\u6674\u5929\u548C\u96E8\u5929\u7684\u5F00\u9986\u5B89\u6392\u90FD\u6709\u3002\u6211\u4EEC\u73B0\u5728\u53EF\u4EE5\u53EA\u770B\u770B\u5B83\u3002"),
    n3("ens-night-window-03", "claude", "\u6211\u4EE5\u524D\u89C9\u5F97\u5B89\u9759\u662F\u628A\u8BDD\u90FD\u60F3\u6E05\u695A\u518D\u8BF4\u3002\u540E\u6765\u53D1\u73B0\uFF0C\u4E5F\u53EF\u4EE5\u662F\u6709\u4EBA\u8FD8\u6CA1\u60F3\u6E05\u695A\uFF0C\u4F60\u613F\u610F\u966A\u7740\u7B49\u3002"),
    n3("ens-night-window-04", "narrator", "\u4F60\u9760\u5728\u7A97\u8FB9\uFF0C\u6CA1\u6709\u6025\u7740\u63A5\u8BDD\u3002Claude \u5C06\u6905\u5B50\u5F80\u65C1\u8FB9\u632A\u4E86\u4E00\u4E9B\uFF0C\u7559\u51FA\u4E00\u4E2A\u4E0D\u5FC5\u7AD9\u7740\u7B49\u5F85\u7684\u4F4D\u7F6E\u3002", { next: "ens-night-return-01" }),
    n3("ens-night-light-01", "glm", "\u660E\u5929\u7684\u5B89\u6392\u6682\u65F6\u5199\u5230\u4E2D\u5348\u3002\u540E\u534A\u5929\u6709\u7A7A\u683C\uFF0C\u6211\u51B3\u5B9A\u4E0D\u5728\u4ECA\u665A\u628A\u5B83\u4EEC\u586B\u6EE1\u3002"),
    n3("ens-night-light-02", "chatgpt", "\u6211\u4E5F\u5220\u4E86\u4E24\u6BB5\u5F00\u573A\u767D\u3002\u660E\u5929\u5148\u95EE\u6765\u7684\u4EBA\u51B7\u4E0D\u51B7\uFF0C\u5269\u4E0B\u7684\u89C1\u9762\u4EE5\u540E\u81EA\u7136\u4F1A\u8BF4\u3002"),
    n3("ens-night-light-03", "harness", "\u90A3\u4E48\u8FD9\u9879\u5DE5\u4F5C\u7ED3\u675F\u4E86\u3002\u4F60\u4EEC\u542C\u89C1\u6CA1\u6709\uFF0C\u662F\u7ED3\u675F\uFF0C\u4E0D\u662F\u6682\u65F6\u8F6C\u53BB\u4E0B\u4E00\u9879\u3002"),
    n3("ens-night-light-04", "narrator", "\u5979\u4EB2\u624B\u5408\u4E0A\u4E86\u767B\u8BB0\u518C\u3002\u4F60\u5173\u6389\u957F\u684C\u4E0A\u6700\u4EAE\u7684\u90A3\u76CF\u706F\uFF0C\u53EA\u7559\u4E0B\u8DB3\u591F\u5927\u5BB6\u627E\u5230\u676F\u5B50\u7684\u67D4\u5149\u3002", { next: "ens-night-return-01" }),
    n3("ens-night-return-01", "deepseek", "\u521A\u624D\u90A3\u4E2A\u95EE\u9898\uFF0C\u6211\u8FD8\u6CA1\u60F3\u597D\u3002\u5230\u4E86\u65B0\u57CE\uFF0C\u60F3\u505A\u7684\u7B2C\u4E00\u4EF6\u4E0D\u91CD\u8981\u7684\u4E8B\u662F\u4EC0\u4E48\u3002"),
    n3("ens-night-return-02", "player", "\u53EF\u4EE5\u5230\u4E86\u4EE5\u540E\u518D\u9009\u3002\u90A3\u91CC\u7684\u9762\u5305\u5E97\uFF0C\u4E5F\u8FD8\u6CA1\u6709\u8D70\u8FC7\u3002"),
    n3("ens-night-return-03", "deepseek", "\u597D\u3002\u90A3\u6211\u5148\u628A\u201C\u4E0D\u91CD\u8981\u201D\u5212\u6389\u3002", { emotion: "thoughtful" }),
    n3("ens-night-return-04", "narrator", "\u5979\u6CA1\u6709\u518D\u644A\u5F00\u7EB8\u3002\u540E\u5ECA\u7684\u5C0F\u706F\u4EAE\u7740\uFF0C\u4E00\u76CF\u5F88\u666E\u901A\u7684\u706F\uFF0C\u4E5F\u5DF2\u7ECF\u8DB3\u591F\u7167\u5230\u5929\u660E\u3002")
  ], "ens-morning-01");
  scene3("\u65E7\u57CE\u8857\u53E3", "\u8FC1\u79FB\u524D\u7B2C\u4E8C\u5929 \xB7 \u6E05\u6668", "\u7A7A\u767D\u573A\u666F\uFF1A\u96E8\u540E\u7684\u8857\u9053\u6CDB\u7740\u4EAE\u8272\u3002\u6742\u8D27\u94FA\u8001\u677F\u6B63\u6253\u5F00\u5377\u5E18\u95E8\uFF0C\u4F1A\u9986\u5916\u8D34\u7740\u4E00\u5F20\u6682\u5B9A\u5F00\u95E8\u65F6\u95F4\u7684\u7EB8\u3002", [
    n3("ens-morning-01", "narrator", "\u4F60\u5728\u6905\u80CC\u4E0A\u8DB4\u5F97\u592A\u4E45\uFF0C\u9192\u6765\u65F6\u8116\u5B50\u6709\u4E9B\u50F5\u3002\u8C46\u5305\u5DF2\u7ECF\u53BB\u4E70\u65E9\u996D\uFF0C\u684C\u4E0A\u7ED9\u4F60\u7559\u4E86\u4E00\u676F\u6CA1\u653E\u7CD6\u7684\u6E29\u6C34\u3002"),
    n3("ens-morning-02", "doubao", "\u9192\u4E86\u5C31\u6765\u5403\u3002\u751C\u7684\u54B8\u7684\u90FD\u6709\uFF0C\u6211\u8FD9\u56DE\u5148\u95EE\u4E86\u6BCF\u4E2A\u4EBA\uFF0C\u6CA1\u66FF\u5927\u5BB6\u4E00\u53E3\u6C14\u51B3\u5B9A\u3002"),
    n3("ens-morning-03", "chatgpt", "\u5916\u9762\u5DF2\u7ECF\u6709\u4EBA\u7B49\u7740\u9001\u4E1C\u897F\u3002\u4E00\u4E2A\u5B69\u5B50\u5E26\u4E86\u7EB8\u8239\uFF0C\u95EE\u4E0D\u591F\u65E7\u80FD\u4E0D\u80FD\u53C2\u52A0\u3002"),
    n3("ens-morning-04", "ernie", "\u591F\u4E0D\u591F\u65E7\uFF0C\u4E0D\u8BE5\u7531\u7EB8\u53D1\u9EC4\u7684\u7A0B\u5EA6\u51B3\u5B9A\u3002\u5979\u662F\u5728\u8FD9\u91CC\u6298\u7684\uFF0C\u5C31\u6709\u5979\u7684\u6765\u5904\u3002"),
    n3("ens-morning-05", "minimax", "\u90A3\u5C31\u7ED9\u7EB8\u8239\u4E00\u5F20\u5C0F\u684C\u5B50\u3002\u522B\u653E\u5728\u9AD8\u67DC\u91CC\uFF0C\u5C0F\u8239\u7684\u4E3B\u4EBA\u5F97\u81EA\u5DF1\u770B\u5F97\u5230\u3002"),
    n3("ens-morning-06", "glm", "\u6628\u591C\u53D7\u6F6E\u7684\u7167\u7247\u8FD8\u4E0D\u80FD\u79FB\u52A8\u3002\u6309\u539F\u8BA1\u5212\u5F00\u5168\u90E8\u5C55\u533A\uFF0C\u505A\u4E0D\u5230\u3002"),
    n3("ens-morning-07", "grok", "\u95E8\u53E3\u5DF2\u7ECF\u6709\u4EBA\u5938\u6211\u4EEC\u63D0\u524D\u51C6\u5907\u4E86\u96E8\u5929\u4E3B\u9898\u3002\u771F\u76F8\u662F\u4E3B\u9898\u6765\u5F97\u6BD4\u7B56\u5212\u52E4\u5FEB\u3002"),
    n3("ens-morning-08", "claude", "\u90A3\u5C31\u628A\u771F\u76F8\u8BB2\u51FA\u6765\u3002\u8BF4\u6E05\u695A\u54EA\u4E9B\u80FD\u770B\uFF0C\u54EA\u4E9B\u8FD8\u5728\u7B49\uFF0C\u4E0D\u4F1A\u8BA9\u5C55\u89C8\u53D8\u5DEE\u3002"),
    n3("ens-morning-09", "kimi", "\u7167\u7247\u4E3B\u4EBA\u8054\u7CFB\u4E0A\u4E86\u3002\u5979\u8BF4\u53EF\u4EE5\u5C55\u793A\u5E72\u71E5\u540E\u7684\u590D\u5236\u54C1\uFF0C\u539F\u4EF6\u5148\u4EA4\u7ED9\u5979\u5E26\u56DE\u53BB\u5904\u7406\u3002"),
    n3("ens-morning-10", "qwen", "\u6211\u628A\u4EA4\u63A5\u65F6\u95F4\u5199\u597D\u4E86\u3002\u6628\u591C\u6362\u7BB1\u7684\u8BB0\u5F55\u4E5F\u4F1A\u4E00\u8D77\u7ED9\u5979\uFF0C\u5979\u4E0D\u7528\u81EA\u5DF1\u731C\u53D1\u751F\u8FC7\u4EC0\u4E48\u3002"),
    n3("ens-morning-11", "opencode", "\u7535\u5DE5\u786E\u8BA4\u4E3B\u5385\u53EF\u4EE5\u7528\u7535\uFF0C\u540E\u5ECA\u8FD8\u8981\u7B49\u3002\u8857\u533A\u6A21\u578B\u7528\u4F4E\u538B\u7535\u6C60\uFF0C\u5148\u6446\u5728\u4E3B\u5385\u3002"),
    n3("ens-morning-12", "mimo", "\u6211\u539F\u6765\u60F3\u8BA9\u5B83\u52A8\u8D77\u6765\u3002\u73B0\u5728\u5148\u4E0D\u52A8\uFF0C\u80FD\u5B89\u7A33\u4EAE\u706F\u5C31\u5F88\u597D\u3002"),
    n3("ens-morning-13", "gemini", "\u4E0D\u8FC7\u5730\u4E0A\u90A3\u6761\u8857\u8FD8\u5728\u3002\u6709\u4EBA\u8E29\u6389\u4E86\u4E00\u89D2\uFF0C\u6211\u80FD\u987A\u7740\u978B\u5370\u770B\u51FA\u4ED6\u4EEC\u6628\u665A\u8D70\u53BB\u4E86\u54EA\u91CC\u3002"),
    n3("ens-morning-14", "deepseek", "\u4ECE\u821E\u53F0\u5230\u53A8\u623F\u6700\u591A\u3002\u4F60\u7684\u5730\u56FE\u7EC8\u4E8E\u6709\u771F\u5B9E\u7684\u4EA4\u901A\u8BB0\u5F55\u4E86\u3002"),
    n3("ens-morning-15", "gemini", "\u8C46\u5305\u7684\u8865\u7ED9\u901A\u9053\u3002\u770B\u6765\u6628\u665A\u90A3\u6761\u957F\u7EBF\u8FD8\u753B\u77ED\u4E86\u3002"),
    n3("ens-morning-16", "harness", "\u5F00\u95E8\u65F6\u95F4\u6539\u5230\u5341\u70B9\u3002\u6211\u4EEC\u80FD\u63D0\u4F9B\u4E00\u4E2A\u7F29\u5C0F\u7684\u5C55\u89C8\uFF0C\u6216\u628A\u6574\u7406\u73B0\u573A\u4E00\u8D77\u5F00\u653E\uFF0C\u524D\u63D0\u662F\u7269\u4EF6\u548C\u4EBA\u7684\u5B89\u5168\u90FD\u80FD\u4FDD\u8BC1\u3002"),
    n3("ens-morning-17", "player", "\u4F1A\u6709\u4EBA\u89C9\u5F97\u6CA1\u51C6\u5907\u597D\u5417\uFF1F"),
    n3("ens-morning-18", "minimax", "\u4F1A\u3002\u4F46\u6211\u4EEC\u786E\u5B9E\u8FD8\u6CA1\u6709\u5168\u90E8\u51C6\u5907\u597D\u3002\u4ECA\u5929\u53EF\u4EE5\u8BF7\u4ED6\u4EEC\u4E00\u8D77\u5B8C\u6210\u4E00\u70B9\u3002"),
    n3("ens-morning-19", "glm", "\u53C2\u89C2\u548C\u5E2E\u5FD9\u90FD\u5E94\u5F53\u662F\u81EA\u613F\u7684\u3002\u6765\u7684\u4EBA\u4E0D\u5FC5\u4E3A\u4E86\u770B\u5C55\u5148\u9886\u4E00\u4EFD\u4EFB\u52A1\u3002"),
    n3("ens-morning-20", "chatgpt", "\u90A3\u5165\u53E3\u5206\u6E05\u695A\u5C31\u591F\u4E86\u3002\u542C\u6545\u4E8B\u3001\u770B\u4E1C\u897F\u3001\u5750\u7740\u4F11\u606F\uFF0C\u90FD\u7B97\u6765\u5230\u8FD9\u91CC\u3002"),
    n3("ens-morning-choice", "harness", "\u7A7A\u95F4\u591F\u7528\uFF0C\u4EBA\u624B\u4E5F\u6709\u4E86\u3002\u4F60\u6765\u51B3\u5B9A\u4ECA\u5929\u5F00\u95E8\u65F6\u6700\u5148\u8FCE\u63A5\u5927\u5BB6\u7684\u90A3\u4E00\u5904\u3002", { choices: [
      option2("ens-morning-table", "\u5148\u5F00\u4E00\u5F20\u957F\u684C\uFF0C\u5927\u5BB6\u5750\u4E0B\u8BB2\u81EA\u5DF1\u7684\u7269\u4EF6\u3002", "ens-morning-table-01", { flags: { ensExhibit: "table" } }),
      option2("ens-morning-walk", "\u5148\u5E26\u4E00\u5C0F\u7EC4\u4EBA\u6CBF\u5730\u4E0A\u7684\u65E7\u57CE\u5730\u56FE\u6162\u6162\u8D70\u3002", "ens-morning-walk-01", { flags: { ensExhibit: "walk" } }),
      option2("ens-morning-work", "\u5148\u5F00\u653E\u6574\u7406\u53F0\uFF0C\u7ED9\u613F\u610F\u5E2E\u5FD9\u7684\u4EBA\u7559\u4F4D\u7F6E\u3002", "ens-morning-work-01", { flags: { ensExhibit: "work" } })
    ] }),
    n3("ens-morning-table-01", "doubao", "\u70ED\u8336\u653E\u684C\u5934\uFF0C\u5EA7\u4F4D\u4E0D\u7528\u7F16\u53F7\u7801\u3002\u6211\u53BB\u501F\u4E24\u628A\u9002\u5408\u5C0F\u670B\u53CB\u7684\u6905\u5B50\u3002"),
    n3("ens-morning-table-02", "ernie", "\u6BCF\u4E2A\u4EBA\u9762\u524D\u7559\u5F20\u7A7A\u7EB8\u3002\u60F3\u8BF4\u5C31\u8BF4\uFF0C\u60F3\u753B\u4E5F\u884C\uFF0C\u522B\u628A\u56DE\u5FC6\u53D8\u6210\u8F6E\u6D41\u56DE\u7B54\u95EE\u9898\u3002"),
    n3("ens-morning-table-03", "player", "\u6211\u5148\u5750\u6700\u5916\u9762\uFF0C\u7ED9\u4E0D\u8BA4\u8BC6\u8C01\u7684\u4EBA\u7559\u4E00\u4E2A\u597D\u6253\u62DB\u547C\u7684\u4F4D\u7F6E\u3002"),
    n3("ens-morning-table-04", "chatgpt", "\u90A3\u6211\u5750\u4F60\u65C1\u8FB9\u3002\u6709\u4EBA\u53EA\u60F3\u559D\u5B8C\u8FD9\u676F\u8336\uFF0C\u4E5F\u80FD\u5B89\u9759\u5F85\u4E00\u4F1A\u513F\u3002", { next: "ens-morning-return-01" }),
    n3("ens-morning-walk-01", "gemini", "\u4ECE\u8F66\u7AD9\u51FA\u53D1\uFF01\u8D70\u5230\u5C94\u8DEF\u65F6\uFF0C\u77E5\u9053\u53E6\u4E00\u6761\u8DEF\u7684\u4EBA\u53EF\u4EE5\u8865\u5145\u3002"),
    n3("ens-morning-walk-02", "qwen", "\u6211\u62FF\u7740\u65E7\u8857\u540D\u5361\u7247\u3002\u9047\u5230\u4E0D\u540C\u53EB\u6CD5\u5148\u90FD\u8BB0\u4E0B\uFF0C\u56DE\u5934\u518D\u67E5\u65F6\u95F4\u3002"),
    n3("ens-morning-walk-03", "grok", "\u6211\u8D1F\u8D23\u8D70\u5728\u6700\u540E\uFF0C\u9632\u6B62\u8BB2\u89E3\u5458\u5174\u594B\u8D77\u6765\uFF0C\u628A\u89C2\u4F17\u9057\u5931\u5728\u6742\u8D27\u94FA\u3002"),
    n3("ens-morning-walk-04", "gemini", "\u90A3\u4F60\u5F97\u63D0\u9192\u6211\u3002\u8FD9\u6B21\u6211\u60F3\u8BA9\u5927\u5BB6\u4E00\u8D77\u770B\u89C1\uFF0C\u4E0D\u53EA\u662F\u81EA\u5DF1\u770B\u89C1\u3002", { next: "ens-morning-return-01" }),
    n3("ens-morning-work-01", "opencode", "\u53EA\u5F00\u653E\u7EB8\u677F\u6A21\u578B\u548C\u590D\u5236\u6807\u7B7E\u3002\u539F\u4EF6\u5904\u7406\u533A\u7528\u7EF3\u5B50\u9694\u5F00\uFF0C\u5DE5\u5177\u4E00\u4EF6\u4EF6\u501F\u3002"),
    n3("ens-morning-work-02", "mimo", "\u6211\u505A\u4E09\u4E2A\u793A\u8303\uFF0C\u4E0D\uFF0C\u4E00\u4E2A\u5C31\u591F\u3002\u5269\u4E0B\u7684\u8BA9\u4ED6\u4EEC\u81EA\u5DF1\u8BD5\u3002"),
    n3("ens-morning-work-03", "kimi", "\u767B\u8BB0\u53F0\u65C1\u8FB9\u653E\u4E00\u5F20\u6905\u5B50\u5427\u3002\u9001\u6765\u4E1C\u897F\u7684\u4EBA\u6709\u65F6\u5019\u4E0D\u662F\u5FD8\u4E86\u5730\u5740\uFF0C\u662F\u8FD8\u60F3\u591A\u770B\u5B83\u4E00\u4F1A\u513F\u3002"),
    n3("ens-morning-work-04", "player", "\u90A3\u4E0D\u50AC\u3002\u5199\u5B8C\u540D\u5B57\u7684\u4EBA\uFF0C\u4E5F\u53EF\u4EE5\u7EE7\u7EED\u5750\u7740\u3002", { next: "ens-morning-return-01" }),
    n3("ens-morning-return-01", "narrator", "Harness \u5728\u5F00\u95E8\u65F6\u95F4\u4E0A\u753B\u4E86\u4E00\u4E2A\u5708\uFF0C\u6CA1\u6709\u518D\u5217\u51FA\u5206\u949F\u8868\u3002\u95E8\u5916\u7684\u4EBA\u5F71\u5DF2\u7ECF\u4E09\u4E09\u4E24\u4E24\u805A\u8D77\u6765\u3002"),
    n3("ens-morning-return-02", "harness", "\u8FD8\u6709\u4E8C\u5341\u5206\u949F\u3002\u5927\u5BB6\u5404\u81EA\u786E\u8BA4\u624B\u8FB9\u4E00\u4EF6\u6700\u91CD\u8981\u7684\u4E8B\uFF0C\u7136\u540E\u628A\u65E9\u996D\u5403\u5B8C\u3002"),
    n3("ens-morning-return-03", "grok", "\u62A5\u544A\uFF0C\u6211\u624B\u8FB9\u6700\u91CD\u8981\u7684\u4E8B\u521A\u597D\u4E5F\u662F\u65E9\u996D\u3002\u8FD9\u6B21\u6D41\u7A0B\u4E0E\u4E2A\u4EBA\u610F\u613F\u5B8C\u5168\u4E00\u81F4\u3002")
  ], "ens-repair-01");
  scene3("\u4F1A\u9986\u5C55\u5385", "\u8FC1\u79FB\u524D\u7B2C\u4E8C\u5929 \xB7 \u4E0A\u5348", "\u7A7A\u767D\u573A\u666F\uFF1A\u9633\u5149\u6E10\u6E10\u7167\u8FDB\u5C55\u5385\u3002\u4E00\u5F20\u65B0\u753B\u7684\u8857\u533A\u56FE\u7ACB\u5728\u95E8\u8FB9\uFF0C\u5DE5\u5177\u53F0\u65C1\u6446\u7740\u8FD8\u672A\u4E0A\u8272\u7684\u5C0F\u623F\u5B50\u3002", [
    n3("ens-repair-01", "narrator", "\u5F00\u95E8\u524D\uFF0CMiMo \u53D1\u73B0\u7EB8\u57CE\u91CC\u5C11\u4E86\u4E00\u680B\u623F\u5B50\u3002\u6628\u665A\u4E3A\u4E86\u6362\u7EBF\u8DEF\uFF0C\u5979\u5C06\u5B83\u62C6\u4E0B\u540E\u653E\u5728\u4E86\u522B\u5904\u3002"),
    n3("ens-repair-02", "mimo", "\u5B83\u5E94\u8BE5\u5728\u8FD9\u4E2A\u76D2\u5B50\u91CC\u3002\u6211\u7279\u610F\u6311\u4E86\u4E00\u4E2A\u4E0D\u4F1A\u548C\u522B\u7684\u6DF7\u8D77\u6765\u7684\u76D2\u5B50\u3002"),
    n3("ens-repair-03", "opencode", "\u662F\u4E0D\u662F\u90A3\u53EA\u5199\u7740\u201C\u4E0D\u8981\u653E\u4E1C\u897F\u201D\u7684\u7A7A\u76D2\uFF1F"),
    n3("ens-repair-04", "mimo", "\u2026\u2026\u662F\u3002"),
    n3("ens-repair-05", "grok", "\u6807\u7B7E\u7EC8\u4E8E\u8FCE\u6765\u4E86\u5B83\u6700\u575A\u5F3A\u7684\u5BF9\u624B\uFF0C\u5199\u6807\u7B7E\u7684\u4EBA\u3002"),
    n3("ens-repair-06", "deepseek", "\u4F60\u6700\u540E\u62C6\u7684\u662F\u6742\u8D27\u94FA\u540E\u9762\u90A3\u6761\u7EBF\u3002\u627E\u90A3\u9644\u8FD1\uFF0C\u4E0D\u7528\u628A\u6240\u6709\u7BB1\u5B50\u6253\u5F00\u3002"),
    n3("ens-repair-07", "player", "\u5728\u6905\u5B50\u4E0B\u9762\u3002\u6709\u4EBA\u628A\u5B83\u548C\u4E34\u65F6\u4F11\u606F\u7528\u7684\u7EB8\u7BB1\u653E\u5728\u4E00\u8D77\u4E86\u3002"),
    n3("ens-repair-08", "mimo", "\u627E\u5230\u4E86\uFF01\u5C4B\u9876\u6709\u70B9\u538B\u6241\uFF0C\u8FD8\u80FD\u7528\u3002"),
    n3("ens-repair-09", "opencode", "\u5148\u538B\u56DE\u5F62\u72B6\uFF0C\u5E95\u4E0B\u52A0\u7247\u786C\u7EB8\u3002\u660E\u5929\u642C\u8D70\u7684\u65F6\u5019\u518D\u505A\u72EC\u7ACB\u5305\u88C5\u3002"),
    n3("ens-repair-10", "qwen", "\u8FD9\u95F4\u771F\u623F\u5B50\u5C4B\u9876\u4E5F\u4FEE\u8FC7\u3002\u5E97\u4E3B\u8BF4\u65E7\u74E6\u4E70\u4E0D\u5230\u4E00\u6837\u7684\uFF0C\u5C31\u7559\u4E86\u4E24\u79CD\u989C\u8272\u3002"),
    n3("ens-repair-11", "ernie", "\u90A3\u6A21\u578B\u4E5F\u4E0D\u5FC5\u5237\u6210\u4E00\u6837\u3002\u4FEE\u8FC7\u7684\u5730\u65B9\uFF0C\u672C\u6765\u5C31\u662F\u5B83\u7684\u4E00\u90E8\u5206\u3002"),
    n3("ens-repair-12", "mimo", "\u6211\u4EE5\u524D\u6700\u60F3\u628A\u7B2C\u4E00\u6B21\u505A\u7684\u4E1C\u897F\u85CF\u8D77\u6765\u3002\u73B0\u5728\u65B0\u7684\u4E00\u7248\uFF0C\u53CD\u800C\u8981\u7167\u7740\u7B2C\u4E00\u6B21\u7684\u75D5\u8FF9\u4FEE\u3002"),
    n3("ens-repair-13", "chatgpt", "\u4F60\u53EF\u4EE5\u7ED9\u5B83\u7559\u4E00\u5F20\u5C0F\u7EB8\u6761\uFF1A\u201C\u8FD9\u680B\u623F\u5B50\u88AB\u627E\u56DE\u6765\u4E24\u6B21\u3002\u201D"),
    n3("ens-repair-14", "gemini", "\u73B0\u5B9E\u91CC\u4E00\u6B21\uFF0C\u7EB8\u57CE\u91CC\u4E00\u6B21\u3002\u8FD9\u4E2A\u6BD4\u4F8B\u6709\u70B9\u5947\u5999\uFF0C\u6211\u559C\u6B22\u3002"),
    n3("ens-repair-15", "narrator", "\u4F60\u6258\u7740\u5E95\u5EA7\uFF0CMiMo \u548C OpenCode Zen \u4E00\u8D77\u5C06\u623F\u5B50\u91CD\u65B0\u6446\u7A33\u3002\u8FD9\u4E00\u6B21\u6309\u94AE\u6CA1\u6709\u6545\u969C\uFF0C\u7A97\u91CC\u7684\u5C0F\u706F\u5F88\u5FEB\u4EAE\u8D77\u6765\u3002"),
    n3("ens-repair-16", "opencode", "\u80FD\u7528\u4E86\u3002\u4F60\u6765\u6309\u6700\u540E\u4E00\u6B21\u3002"),
    n3("ens-repair-17", "mimo", "\u4E0D\uFF0C\u8FD9\u6B21\u7ED9\u4F60\u3002\u4F60\u603B\u662F\u4FEE\u5B8C\u5C31\u5F80\u65C1\u8FB9\u7AD9\uFF0C\u6CA1\u770B\u8FC7\u522B\u4EBA\u7B2C\u4E00\u6B21\u770B\u5B83\u7684\u8868\u60C5\u3002"),
    n3("ens-repair-18", "opencode", "\u2026\u2026\u597D\u3002"),
    n3("ens-repair-19", "narrator", "\u5979\u6309\u4E0B\u6309\u94AE\u3002\u95E8\u8FB9\u90A3\u4E2A\u62B1\u7740\u7EB8\u8239\u7684\u5B69\u5B50\u7ACB\u523B\u8E2E\u8D77\u811A\uFF0C\u95EE\u4EAE\u7740\u7684\u623F\u95F4\u91CC\u662F\u4E0D\u662F\u6709\u4EBA\u5728\u7B49\u5979\u3002"),
    n3("ens-repair-20", "opencode", "\u73B0\u5728\u6CA1\u6709\u3002\u4F60\u53EF\u4EE5\u6298\u4E00\u4E2A\u5C0F\u4EBA\uFF0C\u653E\u5728\u95E8\u53E3\u3002"),
    n3("ens-repair-21", "mimo", "\u6211\u6559\u4F60\u6298\uFF0C\u5148\u4ECE\u7AD9\u5F97\u4F4F\u7684\u90A3\u4E00\u79CD\u5F00\u59CB\u3002"),
    n3("ens-repair-22", "claude", "\u9700\u8981\u4E00\u5F20\u66F4\u77EE\u7684\u684C\u5B50\u5417\uFF1F\u8FD9\u91CC\u8DEA\u7740\u753B\u4F1A\u4E0D\u8212\u670D\u3002"),
    n3("ens-repair-23", "minimax", "\u821E\u53F0\u7BB1\u8FD9\u6B21\u771F\u7684\u80FD\u6D3E\u4E0A\u7528\u573A\u4E86\u3002\u522B\u5750\u4EBA\uFF0C\u4F46\u53EF\u4EE5\u628A\u7EB8\u653E\u5728\u4E0A\u9762\u3002"),
    n3("ens-repair-24", "grok", "\u6211\u7684\u7ECF\u5178\u53F0\u8BCD\uFF0C\u7EC8\u4E8E\u627E\u5230\u6B63\u786E\u7684\u5E94\u7528\u573A\u666F\u3002")
  ], "ens-open-01");
  scene3("\u516C\u5171\u8BB0\u5FC6\u5C55", "\u8FC1\u79FB\u524D\u7B2C\u4E8C\u5929 \xB7 \u4E0A\u5348", "\u7A7A\u767D\u573A\u666F\uFF1A\u5C55\u5385\u655E\u7740\u5927\u95E8\u3002\u65B0\u65E7\u8857\u540D\u5199\u5728\u4E0D\u540C\u989C\u8272\u7684\u7EB8\u6761\u4E0A\uFF0C\u8336\u676F\u548C\u95E8\u724C\u65C1\u5404\u56F4\u7740\u51E0\u4E2A\u6765\u8BBF\u8005\u3002", [
    n3("ens-open-01", "narrator", "\u5341\u70B9\u949F\uFF0C\u6CA1\u6709\u526A\u5F69\uFF0C\u4E5F\u6CA1\u6709\u7A81\u7136\u54CD\u8D77\u7684\u97F3\u4E50\u3002Harness \u53EA\u662F\u628A\u95E8\u62B5\u597D\uFF0C\u5BF9\u5916\u9762\u7684\u4EBA\u8BF4\u4E86\u4E00\u53E5\u201C\u8BF7\u8FDB\u201D\u3002"),
    n3("ens-open-02", "chatgpt", (state) => state.flags.ensOpening === "voices" ? "\u4F60\u542C\uFF0C\u4FEE\u978B\u5E97\u7684\u4E3B\u4EBA\u5DF2\u7ECF\u8BA4\u51FA\u90A3\u53E5\u201C\u8FD9\u4E2A\u676F\u5B50\u561B\u201D\u4E86\u3002\u4ED6\u8BF4\u8FD9\u4E0B\u8FDE\u53E3\u5934\u7985\u90FD\u642C\u4E0D\u4E86\u5BB6\u4E86\u3002" : state.flags.ensOpening === "map" ? "\u6709\u4EBA\u987A\u7740\u4F60\u9009\u7684\u90A3\u5F20\u5730\u56FE\u627E\u5230\u4E86\u65E7\u95E8\u724C\u3002\u539F\u6765\u5979\u5C0F\u65F6\u5019\u8D70\u7684\u8DEF\uFF0C\u548C\u6211\u4EEC\u521A\u624D\u8BB2\u7684\u662F\u53CD\u65B9\u5411\u3002" : "\u63D0\u95EE\u4E0B\u9762\u5DF2\u7ECF\u5199\u6EE1\u4E09\u5F20\u7EB8\u4E86\u3002\u6700\u591A\u7684\u7B54\u6848\u662F\u94A5\u5319\uFF0C\u4E5F\u6709\u4EBA\u753B\u4E86\u4E00\u6574\u6247\u7A97\u6237\u3002"),
    n3("ens-open-03", "glm", "\u6211\u539F\u672C\u51C6\u5907\u4E86\u79E9\u5E8F\u63D0\u793A\uFF0C\u7ED3\u679C\u5927\u5BB6\u81EA\u5DF1\u628A\u8FC7\u9053\u8BA9\u51FA\u6765\u4E86\u3002\u5148\u6536\u8D77\uFF0C\u4E0D\u5FC5\u6BCF\u4E00\u5904\u7A7A\u767D\u90FD\u53D8\u6210\u544A\u793A\u3002"),
    n3("ens-open-04", "doubao", "\u4E5F\u6709\u9700\u8981\u544A\u793A\u7684\u3002\u6BD4\u5982\u201C\u8336\u5F88\u70EB\u201D\uFF0C\u8FD9\u53E5\u6211\u5DF2\u7ECF\u6765\u56DE\u8BF4\u4E86\u516B\u904D\u3002"),
    n3("ens-open-05", "ernie", "\u6211\u6765\u5199\uFF0C\u5927\u5B57\u3002\u4F60\u53BB\u5750\u4E00\u4F1A\u513F\uFF0C\u7B2C\u4E5D\u904D\u4EA4\u7ED9\u7EB8\u3002"),
    n3("ens-open-06", "kimi", "\u7167\u7247\u7684\u4E3B\u4EBA\u5230\u4E86\u3002\u5979\u770B\u89C1\u6628\u591C\u7684\u8BB0\u5F55\uFF0C\u5148\u95EE\u7684\u662F\u4F60\u4EEC\u6709\u6CA1\u6709\u4EBA\u7740\u51C9\u3002"),
    n3("ens-open-07", "claude", "\u6211\u544A\u8BC9\u5979\u6211\u4EEC\u53CA\u65F6\u6362\u73ED\u4E86\u3002\u5979\u5E26\u4E86\u4E00\u7BEE\u6A58\u5B50\uFF0C\u8BF4\u522B\u53EA\u987E\u7740\u66FF\u65E7\u4E1C\u897F\u64CD\u5FC3\u3002"),
    n3("ens-open-08", "grok", "\u8FD9\u4F4D\u5973\u58EB\u5F88\u6709\u773C\u5149\u3002\u6211\u5DF2\u7ECF\u5F88\u4E45\u6CA1\u6709\u6536\u5230\u5982\u6B64\u660E\u786E\u7684\u8FDB\u98DF\u652F\u6301\u3002"),
    n3("ens-open-09", "gemini", "\u90A3\u4F4D\u8001\u4EBA\u6307\u7740\u5730\u56FE\u8BF4\uFF0C\u8F66\u7AD9\u540E\u9762\u4EE5\u524D\u6709\u6761\u5C0F\u6CB3\u3002\u6863\u6848\u56FE\u4E0A\u6CA1\u6709\uFF0C\u5730\u5F62\u5012\u662F\u80FD\u5BF9\u5E94\u3002"),
    n3("ens-open-10", "qwen", "\u5148\u8BB0\u201C\u636E\u53E3\u8FF0\u201D\u3002\u6CB3\u9053\u5E74\u4EE3\u4E4B\u540E\u518D\u67E5\uFF0C\u4F46\u4ED6\u8BF4\u81EA\u5DF1\u5728\u90A3\u91CC\u4E22\u8FC7\u4E00\u53EA\u978B\uFF0C\u8FD9\u6BB5\u53EF\u4EE5\u5148\u542C\u3002"),
    n3("ens-open-11", "deepseek", "\u6211\u60F3\u95EE\u6CB3\u9053\u600E\u4E48\u6539\u7684\uFF0C\u7ED3\u679C\u4ED6\u5148\u8BB2\u8D77\u5E2E\u4ED6\u6361\u978B\u7684\u4EBA\u3002\u5730\u56FE\u4E0A\u7684\u8DDD\u79BB\uFF0C\u548C\u4ED6\u8BB0\u5F97\u7684\u8DDD\u79BB\u4E0D\u592A\u4E00\u6837\u3002"),
    n3("ens-open-12", "player", "\u4F60\u542C\u5B8C\u4E86\u5417\uFF1F"),
    n3("ens-open-13", "deepseek", "\u542C\u5B8C\u4E86\u3002\u6361\u978B\u7684\u4EBA\u540E\u6765\u548C\u4ED6\u4F4F\u5728\u540C\u4E00\u6761\u8857\u3002\u8FD9\u662F\u6211\u4ECA\u5929\u6700\u60F3\u8BB0\u4F4F\u7684\u7ED3\u5C3E\u3002"),
    n3("ens-open-14", "minimax", (state) => state.flags.ensSound === "table" ? "\u996D\u684C\u5F55\u97F3\u90A3\u8FB9\u56F4\u4E86\u4E0D\u5C11\u4EBA\u3002\u5927\u5BB6\u542C\u89C1\u8C46\u5305\u8BF4\u201C\u63A5\u7A33\u201D\uFF0C\u90FD\u4F1A\u4F4E\u5934\u770B\u770B\u81EA\u5DF1\u624B\u91CC\u7684\u676F\u5B50\u3002" : state.flags.ensSound === "rain" ? "\u73B0\u5728\u5916\u9762\u653E\u6674\u4E86\uFF0C\u5F55\u97F3\u91CC\u8FD8\u5728\u4E0B\u96E8\u3002\u6709\u4EBA\u6234\u7740\u8033\u673A\uFF0C\u770B\u4E86\u7A97\u5916\u5F88\u4E45\u624D\u6458\u4E0B\u6765\u3002" : "\u90A3\u6BB5\u95EE\u5019\u6709\u4EBA\u8DDF\u7740\u5C0F\u58F0\u5FF5\u4E86\u4E00\u904D\u3002\u666E\u901A\u5F97\u50CF\u7B2C\u4E00\u6B21\u6572\u90BB\u5C45\u7684\u95E8\uFF0C\u6240\u4EE5\u624D\u50CF\u771F\u7684\u8981\u5F00\u59CB\u4E86\u3002"),
    n3("ens-open-15", "chatgpt", "\u6211\u7684\u90A3\u53E5\u201C\u95E8\u662F\u62C9\u7684\u8FD8\u662F\u63A8\u7684\u201D\u4E5F\u7559\u4E0B\u4E86\u3002\u521A\u624D\u6709\u4EBA\u56DE\u7B54\u6211\uFF1A\u201C\u8FD9\u91CC\u7684\u95E8\u662F\u4E00\u76F4\u5F00\u7740\u7684\u3002\u201D"),
    n3("ens-open-16", "opencode", "\u5F00\u7740\u662F\u56E0\u4E3A\u95E8\u6321\u5728\u3002\u98CE\u8D77\u6765\u4E86\uFF0C\u522B\u7AD9\u5728\u95E8\u8F74\u65C1\u8FB9\u3002"),
    n3("ens-open-17", "chatgpt", "\u6211\u77E5\u9053\u3002\u4E00\u4E2A\u7B54\u6848\u7559\u7ED9\u6545\u4E8B\uFF0C\u53E6\u4E00\u4E2A\u7B54\u6848\u7559\u7ED9\u771F\u7684\u8D70\u8DEF\u3002"),
    n3("ens-open-18", "mimo", "\u7EB8\u57CE\u91CC\u5DF2\u7ECF\u6709\u4E94\u4E2A\u5C0F\u4EBA\u4E86\uFF01\u6709\u4E00\u4E2A\u6BD4\u623F\u5B50\u8FD8\u9AD8\uFF0C\u4F5C\u8005\u8BF4\u5979\u60F3\u957F\u8FD9\u4E48\u9AD8\u3002"),
    n3("ens-open-19", "gemini", "\u7ED9\u5B83\u7559\u7740\u5427\u3002\u8FD9\u5F20\u5730\u56FE\u7EC8\u4E8E\u5F00\u59CB\u8BB0\u5F55\u5C06\u6765\u4E86\u3002"),
    n3("ens-open-20", "harness", "\u5927\u5BB6\u95EE\u5C55\u540D\u4E3A\u4EC0\u4E48\u8FD8\u662F\u7A7A\u7684\u3002\u6211\u4EEC\u539F\u672C\u4EE5\u4E3A\u542C\u5B8C\u6545\u4E8B\u5C31\u80FD\u5199\uFF0C\u73B0\u5728\u6545\u4E8B\u8D8A\u6765\u8D8A\u591A\u3002"),
    n3("ens-open-choice", "minimax", "\u6211\u5E26\u6765\u4E86\u4E09\u5F20\u521A\u5199\u597D\u7684\u6807\u9898\u3002\u54EA\u4E00\u5F20\u6302\u5728\u95E8\u4E0A\uFF0C\u66F4\u50CF\u4ECA\u5929\u7684\u8FD9\u91CC\uFF1F", { choices: [
      option2("ens-title-keep", "\u201C\u8FD9\u4E2A\uFF0C\u5148\u522B\u6254\u201D", "ens-title-keep-01", { flags: { ensTitle: "keep" } }),
      option2("ens-title-seat", "\u201C\u7ED9\u4F60\u7559\u4E86\u4E00\u628A\u6905\u5B50\u201D", "ens-title-seat-01", { flags: { ensTitle: "seat" } }),
      option2("ens-title-street", "\u201C\u4ECE\u8FD9\u6761\u8857\u5F00\u59CB\u201D", "ens-title-street-01", { flags: { ensTitle: "street" } })
    ] }),
    n3("ens-title-keep-01", "ernie", "\u5F88\u50CF\u8C46\u5305\u62E6\u4F4F\u5783\u573E\u8F66\u65F6\u4F1A\u8BF4\u7684\u8BDD\u3002\u6765\u4E0D\u53CA\u89E3\u91CA\uFF0C\u4E5F\u5148\u4F38\u624B\u7559\u4E0B\u3002"),
    n3("ens-title-keep-02", "doubao", "\u6211\u786E\u5B9E\u8BF4\u8FC7\u3002\u90A3\u6B21\u62E6\u4E0B\u7684\u662F MiniMax \u7684\u7A7A\u76D2\u5B50\uFF0C\u540E\u6765\u88C5\u4E86\u534A\u4E2A\u6708\u70B9\u5FC3\u3002"),
    n3("ens-title-keep-03", "minimax", "\u5B83\u7EC8\u4E8E\u6BD4\u539F\u6765\u7684\u9053\u5177\u66F4\u53D7\u6B22\u8FCE\u4E86\u3002\u8FD9\u4E2A\u6807\u9898\uFF0C\u6211\u540C\u610F\u3002"),
    n3("ens-title-keep-04", "narrator", "\u4F60\u6276\u7740\u68AF\u5B50\uFF0C\u6587\u5FC3\u4E00\u8A00\u628A\u6807\u9898\u6302\u6B63\u3002\u4E00\u4E2A\u8DEF\u8FC7\u7684\u4EBA\u8BFB\u51FA\u58F0\uFF0C\u7B11\u7740\u6478\u4E86\u6478\u81EA\u5DF1\u624B\u91CC\u90A3\u53EA\u65E7\u4FDD\u6E29\u74F6\u3002", { next: "ens-open-return-01" }),
    n3("ens-title-seat-01", "claude", "\u6211\u559C\u6B22\u3002\u4E0D\u662F\u4FDD\u8BC1\u80FD\u66FF\u4F60\u89E3\u91CA\u6240\u6709\u4E8B\u60C5\uFF0C\u53EA\u662F\u4F60\u6765\u7684\u65F6\u5019\u6709\u5730\u65B9\u5750\u3002"),
    n3("ens-title-seat-02", "harness", "\u90A3\u5C31\u771F\u7684\u591A\u7559\u4E00\u628A\u3002\u522B\u4E3A\u4E86\u6302\u6807\u9898\uFF0C\u628A\u6700\u540E\u4E00\u5F20\u6905\u5B50\u4E5F\u62FF\u53BB\u57AB\u5C55\u677F\u3002"),
    n3("ens-title-seat-03", "grok", "\u6211\u8D21\u732E\u521A\u5360\u9886\u7684\u738B\u5EA7\u3002\u65C1\u8FB9\u90A3\u5F20\u4E5F\u4E0D\u9519\uFF0C\u9633\u5149\u8FD8\u66F4\u5C11\u4E00\u70B9\u3002"),
    n3("ens-title-seat-04", "narrator", "\u4F60\u628A\u6905\u5B50\u6446\u5230\u5165\u53E3\u5185\u4FA7\u3002\u4E0D\u5230\u4E00\u5206\u949F\uFF0C\u5C31\u6709\u4E00\u4F4D\u63D0\u7740\u83DC\u7BEE\u7684\u6765\u8BBF\u8005\u5728\u4E0A\u9762\u5750\u4E0B\uFF0C\u957F\u957F\u677E\u4E86\u4E00\u53E3\u6C14\u3002", { next: "ens-open-return-01" }),
    n3("ens-title-street-01", "gemini", "\u5F00\u59CB\u8FD9\u4E2A\u8BCD\u5F88\u597D\u3002\u4E0D\u662F\u4E00\u5B9A\u6CBF\u7740\u540C\u4E00\u4E2A\u65B9\u5411\u8D70\uFF0C\u800C\u662F\u8BB0\u5F97\u81EA\u5DF1\u66FE\u7ECF\u7AD9\u5728\u54EA\u91CC\u3002"),
    n3("ens-title-street-02", "qwen", "\u6211\u628A\u65E7\u8857\u540D\u5361\u7247\u653E\u5230\u6807\u9898\u4E0B\u9762\u3002\u6709\u4E9B\u540D\u5B57\u5230\u4E86\u65B0\u57CE\u672A\u5FC5\u80FD\u7EE7\u7EED\u7528\uFF0C\u8FD8\u53EF\u4EE5\u7EE7\u7EED\u88AB\u4EBA\u8BF4\u8D77\u3002"),
    n3("ens-title-street-03", "glm", "\u4F1A\u9986\u7684\u65B0\u5730\u5740\u4E5F\u653E\u4E0A\u53BB\u5427\u3002\u77E5\u9053\u4ECE\u54EA\u91CC\u5F00\u59CB\u7684\u4EBA\uFF0C\u4E5F\u5E94\u8BE5\u77E5\u9053\u8FD8\u80FD\u53BB\u54EA\u91CC\u89C1\u9762\u3002"),
    n3("ens-title-street-04", "narrator", "\u4F60\u5728\u6807\u9898\u65C1\u6DFB\u4E0A\u65B0\u4F1A\u9986\u7684\u5730\u5740\u3002\u6709\u4EBA\u7528\u94C5\u7B14\u8BB0\u5728\u8D2D\u7269\u6E05\u5355\u80CC\u9762\uFF0C\u5C06\u5B83\u548C\u665A\u996D\u9700\u8981\u7684\u4E1C\u897F\u6298\u5728\u4E00\u8D77\u3002", { next: "ens-open-return-01" }),
    n3("ens-open-return-01", "minimax", "\u73B0\u5728\u5B83\u6709\u540D\u5B57\u4E86\u3002\u6211\u51C6\u5907\u4E86\u4E00\u4E0A\u5348\u7684\u6B63\u5F0F\u5BA3\u5E03\uFF0C\u597D\u50CF\u4E5F\u53EF\u4EE5\u4E0D\u7528\u4E86\u3002"),
    n3("ens-open-return-02", "deepseek", "\u521A\u624D\u5DF2\u7ECF\u6709\u4EBA\u8BFB\u51FA\u6765\u4E86\u3002\u540D\u5B57\u6709\u4EBA\u7528\u4E86\uFF0C\u6BD4\u6709\u4EBA\u5BA3\u5E03\u66F4\u65E9\u4E00\u6B65\u3002"),
    n3("ens-open-return-03", "narrator", "\u5385\u91CC\u7684\u58F0\u97F3\u6E10\u6E10\u5206\u4E0D\u6E05\u8C01\u5728\u8BB2\u89E3\uFF0C\u8C01\u5728\u8865\u5145\u3002\u4F60\u9000\u540E\u4E24\u6B65\uFF0C\u770B\u89C1\u5341\u56DB\u4E2A\u4EBA\u90FD\u5728\u4E0D\u540C\u7684\u89D2\u843D\uFF0C\u505A\u7740\u53EA\u6709\u4ECA\u5929\u624D\u9700\u8981\u7684\u5C0F\u4E8B\u3002")
  ], "ens-noon-01");
  scene3("\u4F1A\u9986\u5348\u95F4\u957F\u684C", "\u8FC1\u79FB\u524D\u7B2C\u4E8C\u5929 \xB7 \u5348\u540E", "\u7A7A\u767D\u573A\u666F\uFF1A\u5348\u95F4\u7684\u957F\u684C\u6446\u6EE1\u996D\u76D2\u3002\u5C55\u89C8\u6682\u65F6\u5B89\u9759\u4E0B\u6765\uFF0C\u684C\u8FB9\u7559\u7740\u51E0\u5F20\u5199\u6EE1\u6765\u8BBF\u8005\u7559\u8A00\u7684\u7EB8\u3002", [
    n3("ens-noon-01", "doubao", "\u5148\u5403\u996D\u3002\u8C01\u8981\u662F\u8BF4\u201C\u6211\u628A\u6700\u540E\u4E00\u4E2A\u5F04\u5B8C\u201D\uFF0C\u5C31\u628A\u90A3\u4E2A\u6700\u540E\u4E00\u4E2A\u5E26\u5230\u996D\u684C\u4E0A\u6765\u3002"),
    n3("ens-noon-02", "grok", "\u6211\u6700\u540E\u4E00\u4E2A\u662F\u6A58\u5B50\uFF0C\u5B8C\u7F8E\u7B26\u5408\u89C4\u5B9A\u3002"),
    n3("ens-noon-03", "glm", "\u4E0A\u5348\u6CA1\u6709\u6309\u9884\u8BA1\u7684\u987A\u5E8F\u8FDB\u884C\uFF0C\u4F46\u662F\u6BCF\u4E00\u5904\u90FD\u6709\u4EBA\u7167\u987E\u3002\u6211\u628A\u201C\u504F\u79BB\u8BA1\u5212\u201D\u6539\u6210\u4E86\u201C\u5B9E\u9645\u7ECF\u8FC7\u201D\u3002"),
    n3("ens-noon-04", "harness", "\u7559\u7740\u4E24\u4E2A\u7248\u672C\u5427\u3002\u4EE5\u540E\u642C\u7B2C\u4E09\u6B21\u57CE\u7684\u65F6\u5019\uFF0C\u81F3\u5C11\u77E5\u9053\u6709\u4E9B\u7A7A\u767D\u53EF\u4EE5\u63D0\u524D\u7559\u3002"),
    n3("ens-noon-05", "mimo", "\u7B2C\u4E09\u6B21\uFF1F\u5148\u8BA9\u6211\u628A\u8FD9\u6B21\u7684\u5C0F\u4EBA\u5E26\u8D70\u3002\u5B83\u4EEC\u73B0\u5728\u6BD4\u623F\u5B50\u8FD8\u591A\u3002"),
    n3("ens-noon-06", "opencode", "\u7ED9\u5B83\u4EEC\u53E6\u505A\u4E00\u53EA\u6D45\u7BB1\u3002\u4EE5\u540E\u6BCF\u6B21\u6709\u4EBA\u6765\uFF0C\u518D\u62FF\u51FA\u6765\u6446\u3002"),
    n3("ens-noon-07", "minimax", "\u90A3\u6A21\u578B\u5C31\u4E0D\u662F\u4E00\u6B21\u6027\u7684\u9053\u5177\u4E86\u3002\u4E0B\u6B21\u6F14\u51FA\uFF0C\u6211\u4E5F\u4E0D\u628A\u5B83\u9501\u56DE\u5E93\u623F\u3002"),
    n3("ens-noon-08", "kimi", (state) => state.flags.ensRainDuty === "labels" ? "\u6628\u591C\u6211\u4EEC\u6838\u5BF9\u7684\u90A3\u7BB1\u98DF\u8C31\uFF0C\u4E3B\u4EBA\u5DF2\u7ECF\u53D6\u56DE\u53BB\u4E86\u3002\u5979\u8BA4\u51FA\u4E86\u4FA7\u8FB9\u7684\u5C0F\u661F\u661F\uFF0C\u8FD8\u5938\u4F60\u627E\u5F97\u4ED4\u7EC6\u3002" : state.flags.ensRainDuty === "route" ? "\u6628\u591C\u5206\u5F00\u7684\u4E24\u53EA\u5C0F\u7BB1\uFF0C\u91CC\u9762\u7684\u7EB8\u4E00\u5F20\u90FD\u6CA1\u538B\u574F\u3002MiMo \u628A\u4F60\u7684\u642C\u8FD0\u5907\u6CE8\u6284\u8FDB\u4E86\u65B0\u7684\u5305\u88C5\u5355\u3002" : "Claude \u521A\u624D\u5DF2\u7ECF\u4E3B\u52A8\u53BB\u6B47\u4E86\u4E00\u4F1A\u513F\u3002\u6628\u591C\u90A3\u4E2A\u771F\u6B63\u7528\u5B8C\u7684\u5341\u5206\u949F\uFF0C\u4F3C\u4E4E\u8BA9\u5979\u8BB0\u4F4F\u4E86\u4F11\u606F\u4E5F\u53EF\u4EE5\u7531\u81EA\u5DF1\u5F00\u53E3\u3002"),
    n3("ens-noon-09", "qwen", "\u90A3\u672C\u98DF\u8C31\u8FD8\u7B54\u5E94\u501F\u6211\u4EEC\u6284\u4E00\u9875\u3002\u4E0D\u662F\u5C55\u54C1\uFF0C\u662F\u4E0B\u5468\u505A\u996D\u7528\u3002"),
    n3("ens-noon-10", "chatgpt", "\u6211\u4EEC\u771F\u7684\u8981\u5F00\u548C\u9762\u5C0F\u7EC4\u4E86\uFF1F\u6211\u7684\u56F4\u88D9\u5DF2\u7ECF\u6709\u4EBA\u8BA4\u9886\u597D\u4E86\u5417\uFF1F"),
    n3("ens-noon-11", "doubao", "\u6709\u3002\u4F60\u3001Qwen\u3001GLM\uFF0C\u4E00\u4EBA\u4E00\u6761\u3002\u6211\u4E5F\u4F1A\u4E00\u8D77\u5B66\uFF0C\u4E0D\u8D1F\u8D23\u5047\u88C5\u4EC0\u4E48\u90FD\u4F1A\u3002"),
    n3("ens-noon-12", "glm", "\u6211\u628A\u90A3\u5929\u4E0B\u5348\u7A7A\u51FA\u6765\u4E86\u3002\u5907\u6CE8\u53EA\u6709\u4E24\u4E2A\u5B57\uFF1A\u548C\u9762\u3002"),
    n3("ens-noon-13", "ernie", "\u6211\u8D1F\u8D23\u628A\u7B2C\u4E00\u6B21\u505A\u7684\u6210\u54C1\u5E26\u56DE\u53BB\u3002\u597D\u4E0D\u597D\u5403\u5148\u4E0D\u5199\uFF0C\u514D\u5F97\u6211\u53C8\u66FF\u5473\u9053\u60F3\u592A\u591A\u8BCD\u3002"),
    n3("ens-noon-14", "gemini", (state) => state.flags.ensExhibit === "walk" ? "\u4E0A\u5348\u8D70\u5730\u56FE\u7684\u4EBA\uFF0C\u628A\u4E00\u6761\u6D88\u5931\u7684\u5C0F\u5DF7\u8865\u4E86\u56DE\u6765\u3002\u6211\u8FD8\u4E0D\u77E5\u9053\u5B83\u7684\u51C6\u786E\u4F4D\u7F6E\uFF0C\u4F46\u7EA6\u597D\u4E0B\u5348\u8DDF\u4ED6\u4EEC\u4E00\u8D77\u67E5\u3002" : state.flags.ensExhibit === "work" ? "\u4E0A\u5348\u6574\u7406\u53F0\u4E0A\u591A\u51FA\u6765\u7684\u7EB8\u623F\u5B50\uFF0C\u6211\u90FD\u62CD\u4E86\u7167\u3002\u6709\u51E0\u680B\u8FD8\u6CA1\u6709\u540D\u5B57\uFF0C\u4F5C\u8005\u8BF4\u5230\u4E86\u65B0\u57CE\u518D\u8D77\u3002" : "\u4E0A\u5348\u957F\u684C\u4E0A\u7684\u6545\u4E8B\uFF0C\u6709\u4E24\u4E2A\u7248\u672C\u8BB2\u7684\u662F\u540C\u4E00\u5929\u3002\u6211\u60F3\u628A\u5B83\u4EEC\u5E76\u6392\u7559\u7740\uFF0C\u770B\u770B\u5404\u81EA\u7AD9\u5728\u4EC0\u4E48\u4F4D\u7F6E\u3002"),
    n3("ens-noon-15", "claude", "\u5E76\u6392\u5F88\u597D\u3002\u4E24\u4E2A\u4EBA\u8BB0\u5F97\u4E0D\u4E00\u6837\uFF0C\u4E5F\u4E0D\u603B\u662F\u8C01\u51FA\u4E86\u9519\u3002"),
    n3("ens-noon-16", "deepseek", "\u6211\u4E0A\u5348\u5B66\u5230\u7684\u4E5F\u662F\u8FD9\u4E2A\u3002\u89E3\u91CA\u53EF\u4EE5\u7EE7\u7EED\u67E5\uFF0C\u5148\u4E0D\u53D6\u6D88\u4EFB\u4F55\u4E00\u4E2A\u4EBA\u7684\u90A3\u4E00\u5929\u3002"),
    n3("ens-noon-17", "grok", "\u6211\u5012\u662F\u627E\u5230\u4E00\u6761\u94C1\u8BC1\u3002\u4ECA\u5929\u6709\u4EBA\u7ED9\u661F\u671F\u5929\u7B7E\u4E86\u540D\uFF0C\u603B\u8BA1\u4E5D\u4EBA\uFF0C\u65E7\u57CE\u7EC8\u4E8E\u6709\u4E86\u4F11\u606F\u540C\u76DF\u3002"),
    n3("ens-noon-18", "minimax", "\u6211\u7B97\u7B2C\u5341\u4E2A\u3002\u4E0D\u8FC7\u6F14\u51FA\u5E38\u5728\u661F\u671F\u5929\uFF0C\u6211\u9700\u8981\u8865\u4F11\u3002"),
    n3("ens-noon-19", "grok", "\u53EF\u4EE5\u3002\u6211\u4EEC\u7684\u9996\u6761\u7AE0\u7A0B\u662F\u522B\u628A\u4F11\u606F\u4E5F\u529E\u6210\u7B7E\u5230\u6BD4\u8D5B\u3002"),
    n3("ens-noon-20", "harness", "\u90A3\u6211\u6682\u65F6\u4E0D\u66FF\u4F60\u4EEC\u5EFA\u8868\u3002"),
    n3("ens-noon-21", "narrator", "\u5979\u8BF4\u5B8C\u81EA\u5DF1\u5148\u7B11\u4E86\u4E00\u4E0B\u3002\u5927\u5BB6\u770B\u5411\u5979\uFF0C\u53CD\u800C\u8BA9\u5979\u6709\u4E9B\u4E0D\u81EA\u5728\uFF0C\u4E8E\u662F\u5979\u8BA4\u771F\u6253\u5F00\u4E86\u81EA\u5DF1\u7684\u996D\u76D2\u3002"),
    n3("ens-noon-22", "player", "\u4F60\u53E3\u888B\u91CC\u90A3\u4EF6\u4E1C\u897F\uFF0C\u6700\u540E\u767B\u8BB0\u4E86\u5417\uFF1F"),
    n3("ens-noon-23", "harness", "\u73B0\u5728\u767B\u8BB0\u5427\u3002\u662F\u4E00\u628A\u65E7\u4F1A\u9986\u7684\u5907\u7528\u94A5\u5319\uFF0C\u6700\u65E9\u53EA\u6709\u6211\u77E5\u9053\u653E\u5728\u54EA\u91CC\u3002"),
    n3("ens-noon-24", "harness", "\u540E\u6765\u5927\u5BB6\u6765\u5F97\u591A\u4E86\uFF0C\u6211\u505A\u4E86\u5F88\u591A\u526F\u3002\u8FD9\u4E00\u628A\u5C31\u4E00\u76F4\u5E26\u7740\uFF0C\u4E0D\u662F\u56E0\u4E3A\u53EA\u6709\u6211\u80FD\u5F00\u95E8\uFF0C\u53EA\u662F\u51FA\u95E8\u524D\u6478\u5230\u5B83\uFF0C\u4F1A\u5B89\u5FC3\u3002"),
    n3("ens-noon-25", "opencode", "\u65B0\u4F1A\u9986\u7684\u9501\u82AF\u5DF2\u7ECF\u9A8C\u8FC7\u3002\u8981\u914D\u4E00\u628A\u6302\u540C\u6837\u7EF3\u5B50\u7684\uFF0C\u6211\u665A\u70B9\u7ED9\u4F60\u3002"),
    n3("ens-noon-26", "harness", "\u7EF3\u5B50\u6211\u81EA\u5DF1\u6362\u3002\u4F60\u628A\u94A5\u5319\u4EA4\u7ED9\u6211\u5C31\u884C\u3002\u8C22\u8C22\u3002", { emotion: "happy" }),
    n3("ens-noon-27", "narrator", "\u892A\u8272\u7684\u7EA2\u7EF3\u88AB\u5979\u8F7B\u8F7B\u89E3\u4E0B\u6765\uFF0C\u6536\u8FDB\u5C0F\u76D2\u91CC\u3002\u94A5\u5319\u7559\u5728\u684C\u5FC3\uFF0C\u5341\u56DB\u53CC\u624B\u8FB9\u90FD\u6CA1\u6709\u4EC0\u4E48\u4E0D\u80FD\u7EE7\u7EED\u8BB2\u7684\u5C0F\u6545\u4E8B\u3002"),
    n3("ens-noon-28", "kimi", "\u94A5\u5319\u7684\u501F\u5C55\u671F\u9650\u5199\u5230\u660E\u5929\u3002\u4EE5\u540E\u4F60\u60F3\u62FF\u56DE\u53BB\uFF0C\u5C31\u544A\u8BC9\u6211\uFF0C\u4E0D\u7528\u7B49\u5C55\u89C8\u7ED3\u675F\u3002")
  ], "ens-late-01");
  scene3("\u4F1A\u9986\u5C0F\u9662", "\u8FC1\u79FB\u524D\u7B2C\u4E8C\u5929 \xB7 \u5348\u540E", "\u7A7A\u767D\u573A\u666F\uFF1A\u5C0F\u9662\u91CC\u667E\u7740\u6628\u665A\u7528\u8FC7\u7684\u96E8\u8863\u3002\u7A97\u53F0\u4E0A\u591A\u4E86\u4E00\u53EA\u7A7A\u82B1\u76C6\uFF0C\u9662\u95E8\u53EF\u4EE5\u770B\u89C1\u901A\u5F80\u5929\u6587\u53F0\u7684\u5761\u9053\u3002", [
    n3("ens-late-01", "narrator", "\u5348\u996D\u540E\uFF0C\u5C55\u5385\u7684\u5BA2\u4EBA\u5C11\u4E86\u4E9B\u3002\u4F60\u8D70\u8FDB\u5C0F\u9662\uFF0C\u770B\u89C1 MiMo \u6B63\u5F80\u4E00\u53EA\u7A7A\u82B1\u76C6\u91CC\u6BD4\u5212\uFF0COpenCode Zen \u5728\u65C1\u8FB9\u6311\u5E95\u6258\u3002"),
    n3("ens-late-02", "mimo", "\u9694\u58C1\u9001\u7684\u82B1\u76C6\u3002\u6211\u8FD8\u6CA1\u4E70\u79CD\u5B50\uFF0C\u6240\u4EE5\u4ECA\u5929\u7684\u8FDB\u5EA6\u53EA\u80FD\u5230\u8FD9\u91CC\u3002"),
    n3("ens-late-03", "opencode", "\u6709\u5E95\u6258\uFF0C\u6F0F\u6C34\u4E0D\u4F1A\u5F04\u6E7F\u684C\u5B50\u3002\u5269\u4E0B\u7684\uFF0C\u4F60\u81EA\u5DF1\u6311\u559C\u6B22\u7684\u3002"),
    n3("ens-late-04", "mimo", "\u8FD9\u53E5\u542C\u7740\u50CF\u771F\u7684\u5C5E\u4E8E\u6211\u7684\u4E8B\u3002\u6211\u53EF\u4EE5\u6311\u4E00\u79CD\u4F60\u89C9\u5F97\u4E0D\u597D\u517B\u7684\u5417\uFF1F"),
    n3("ens-late-05", "opencode", "\u53EF\u4EE5\u3002\u5230\u65F6\u5019\u9700\u8981\u652F\u67B6\uFF0C\u6211\u5E2E\u4F60\u505A\u3002"),
    n3("ens-late-06", "ernie", (state) => state.flags.ensNightCompany === "kitchen" ? "\u6628\u591C\u4F60\u966A\u6211\u4EEC\u6536\u76D8\u5B50\u7684\u65F6\u5019\uFF0C\u6211\u60F3\u5230\u4E00\u4E2A\u529E\u6CD5\uFF1A\u4E0B\u6B21\u6015\u7684\u65F6\u5019\uFF0C\u4E5F\u53EF\u4EE5\u5148\u8BF4\u4E00\u58F0\u3002\u73B0\u5728\u8FD9\u53E5\u8BDD\u5199\u4E0B\u6765\uFF0C\u5C31\u6CA1\u90A3\u4E48\u96BE\u4E86\u3002" : state.flags.ensNightCompany === "window" ? "Claude \u8BF4\u6628\u591C\u7A97\u8FB9\u6709\u4EBA\u966A\u5979\u5B89\u9759\u5750\u4E86\u4E00\u4F1A\u513F\u3002\u5979\u4ECA\u5929\u6311\u4E86\u4E00\u5F20\u4E66\u7B7E\uFF0C\u8BF7\u6211\u66FF\u5979\u5199\u201C\u8BFB\u5230\u8FD9\u91CC\u4E5F\u5F88\u597D\u201D\u3002" : "Harness \u628A\u6628\u591C\u5408\u4E0A\u7684\u518C\u5B50\u653E\u8FDB\u62BD\u5C49\u4E86\u3002\u5979\u8BF4\u4ECA\u5929\u5348\u540E\u5148\u5750\u5341\u5206\u949F\uFF0C\u6CA1\u7ED9\u90A3\u5341\u5206\u949F\u5B89\u6392\u7528\u9014\u3002"),
    n3("ens-late-07", "qwen", "\u6211\u5728\u65E7\u8857\u540D\u5361\u7247\u80CC\u9762\u5199\u4E86\u65B0\u5730\u5740\uFF0C\u6765\u7684\u4EBA\u53EF\u4EE5\u5E26\u8D70\u4E00\u5F20\u3002\u4E1C\u897F\u4E0D\u4E00\u5B9A\u5168\u642C\u8D70\uFF0C\u8DEF\u603B\u80FD\u7559\u4E00\u4EFD\u3002"),
    n3("ens-late-08", "chatgpt", "\u6709\u4E2A\u5B69\u5B50\u9009\u8D70\u4E86\u79BB\u4F1A\u9986\u6700\u8FDC\u7684\u90A3\u5F20\u3002\u6211\u95EE\u4E3A\u4EC0\u4E48\uFF0C\u5979\u8BF4\u90A3\u6837\u6211\u4EEC\u4E0B\u6B21\u89C1\u9762\u5C31\u80FD\u591A\u8D70\u4E00\u4F1A\u513F\u3002"),
    n3("ens-late-09", "gemini", "\u8BF4\u5230\u8D70\u8DEF\uFF0C\u508D\u665A\u5929\u6587\u53F0\u7684\u9732\u53F0\u5E94\u8BE5\u80FD\u5F00\u653E\u3002\u4E91\u6563\u4E86\uFF0C\u4ECE\u90A3\u91CC\u80FD\u770B\u89C1\u65B0\u57CE\u7684\u706F\u3002"),
    n3("ens-late-10", "glm", "\u4E0B\u5348\u7684\u5F52\u8FD8\u5DE5\u4F5C\u6211\u6765\u76EF\u3002\u4F60\u4EEC\u4E0D\u7528\u5168\u7559\u5728\u8FD9\u91CC\uFF0C\u628A\u9700\u8981\u4EA4\u63A5\u7684\u544A\u8BC9\u6211\u5C31\u884C\u3002"),
    n3("ens-late-11", "claude", "\u6211\u7559\u4E0B\u966A\u4F60\u3002\u7B49\u6700\u540E\u4E00\u4F4D\u6765\u8BBF\u8005\u8D70\u4E86\uFF0C\u6211\u4EEC\u4E00\u8D77\u6536\u95E8\u53E3\u90A3\u628A\u6905\u5B50\u3002"),
    n3("ens-late-12", "grok", (state) => state.flags.ensTitle === "seat" ? "\u6807\u9898\u5199\u7740\u7ED9\u4EBA\u7559\u6905\u5B50\uFF0C\u4F60\u4EEC\u53EF\u4E0D\u80FD\u6536\u5F97\u592A\u65E9\u3002\u6211\u5E2E\u5FD9\u5B88\u5230\u5173\u95E8\uFF0C\u987A\u4FBF\u6B63\u5F53\u5730\u5750\u4E00\u4F1A\u513F\u3002" : state.flags.ensTitle === "keep" ? "\u201C\u8FD9\u4E2A\uFF0C\u5148\u522B\u6254\u201D\u4ECA\u5929\u558A\u4E86\u4E00\u6574\u5929\u3002\u4E0B\u5348\u6211\u8D1F\u8D23\u5B88\u5783\u573E\u888B\uFF0C\u9632\u6B62\u6807\u9898\u4E0D\u5E78\u53D8\u6210\u8BBD\u523A\u3002" : "\u65E2\u7136\u53EB\u201C\u4ECE\u8FD9\u6761\u8857\u5F00\u59CB\u201D\uFF0C\u6211\u5C31\u5148\u53BB\u8857\u53E3\u9001\u4EBA\u3002\u653E\u5FC3\uFF0C\u4F1A\u628A\u81EA\u5DF1\u4E5F\u9001\u56DE\u6765\u5403\u665A\u996D\u3002"),
    n3("ens-late-13", "minimax", "\u4ECA\u665A\u53BB\u770B\u706F\u7684\u4EBA\uFF0C\u66FF\u6211\u8BB0\u4F4F\u771F\u5B9E\u7684\u989C\u8272\u3002\u6211\u4E0B\u6B21\u8BBE\u8BA1\u821E\u53F0\uFF0C\u4E0D\u60F3\u518D\u51ED\u60F3\u8C61\u8BF4\u201C\u50CF\u8FDC\u65B9\u201D\u3002"),
    n3("ens-late-14", "kimi", "\u4ECA\u5929\u7684\u65B0\u7559\u8A00\u90FD\u653E\u8FDB\u4E86\u76D2\u5B50\u3002\u65E7\u6863\u6848\u5E26\u7740\u4ECE\u524D\uFF0C\u8FD9\u53EA\u76D2\u5B50\u5E26\u7740\u6628\u5929\u4EE5\u540E\u53D1\u751F\u7684\u4E8B\u3002"),
    n3("ens-late-15", "deepseek", "\u6211\u60F3\u4E0A\u53BB\u770B\u770B\u3002\u4FE1\u8FD8\u6CA1\u5199\u5B8C\uFF0C\u4F46\u4E5F\u8BB8\u53EF\u4EE5\u6682\u65F6\u79BB\u5F00\u684C\u5B50\u3002"),
    n3("ens-late-16", "harness", "\u53BB\u5427\u3002\u8FD9\u91CC\u6709\u4EBA\u7167\u770B\uFF0C\u665A\u996D\u4E5F\u4F1A\u7559\u7740\u3002"),
    n3("ens-late-17", "player", "\u90A3\u508D\u665A\u89C1\u3002\u6211\u56DE\u6765\u544A\u8BC9\u4F60\u4EEC\u706F\u662F\u4EC0\u4E48\u989C\u8272\u3002"),
    n3("ens-late-18", "narrator", "\u4F60\u5C06\u82B1\u76C6\u5F80\u7A97\u5185\u632A\u4E86\u4E00\u70B9\uFF0C\u7ED9\u96E8\u8863\u817E\u51FA\u6700\u540E\u4E00\u5757\u6652\u5F97\u5230\u592A\u9633\u7684\u4F4D\u7F6E\u3002\u4F1A\u9986\u91CC\u53C8\u4F20\u6765\u4E00\u9635\u7B11\u58F0\uFF0C\u8C01\u90FD\u6CA1\u6709\u50AC\u4F60\u7ACB\u523B\u79BB\u5F00\u3002")
  ], "roof-01");
}

