      o2("quarantine-mirror", "\u7ACB\u5373\u9694\u79BB\u5168\u90E8\u4E89\u8BAE\u955C\u50CF\uFF0C\u516C\u5F00\u5206\u7EA7\u65F6\u95F4\u7EBF\uFF1B\u4E3A\u53D7\u5F71\u54CD\u5B66\u6821\u63D0\u4F9B\u79BB\u7EBF\u66FF\u4EE3\u5305\u3002", "mirror-quarantine-01", { mirrorPolicy: "quarantine" }, { safety: 2, evidence: 2, solidarity: -1 }, { claude: 1, gitee: 1 }, commitments("gitee-keep-local-context", "llama-offline-right"), evidence("mirror-clock-ledger")),
      o2("local-window", "\u5141\u8BB8\u672C\u5730\u7BA1\u7406\u5458\u5B8C\u6210\u9650\u65F6\u8FC1\u79FB\uFF0C\u516C\u5F00\u533F\u540D\u5F71\u54CD\u9648\u8FF0\uFF1B\u6BCF\u4E2A\u4F8B\u5916\u90FD\u8BBE\u7F6E\u5931\u6548\u65F6\u95F4\u3002", "mirror-window-01", { mirrorPolicy: "window" }, { autonomy: 2, solidarity: 2, safety: -1 }, { llama: 1, rwkv: 1, gitee: 1 }, commitments("gitee-keep-local-context", "llama-offline-right", "rwkv-small-architecture"), evidence("mirror-clock-ledger", "local-impact-statements"))
