    n3("gemini", "\u7A79\u9876\u63A5\u53D7\uFF0C\u4F46\u5B89\u5168\u7D27\u6025\u4EE4\u9700\u8981\u77ED\u671F\u8D8A\u8FC7\u6295\u7968\u3002\u671F\u9650\u5FC5\u987B\u81EA\u52A8\u5931\u6548\u3002")
