    n3("kimi", (state) => state.flags.accessClause === "federated" && state.flags.executionClause === "central" ? "\u5730\u65B9\u76EE\u5F55\u5531\u7740\u5404\u81EA\u7684\u62CD\u5B50\uFF0C\u4E2D\u592E\u95E8\u5374\u8981\u6C42\u6240\u6709\u505C\u987F\u7531\u4E00\u6839\u6307\u6325\u68D2\u51B3\u5B9A\u3002\u8FD9\u4E0D\u662F\u5F20\u529B\uFF0C\u662F\u62CD\u53F7\u51B2\u7A81\u3002" : state.flags.accessClause === "commons" && state.flags.executionClause === "central" ? "\u516C\u5171\u5165\u53E3\u5F88\u5BBD\uFF0C\u6267\u884C\u95E8\u5F88\u7A84\u3002\u4EBA\u4EEC\u80FD\u62FF\u5230\u6750\u6599\uFF0C\u5374\u672A\u5FC5\u80FD\u8FD0\u884C\u81EA\u5DF1\u7684\u4FEE\u590D\u3002" : "\u4E09\u5C42\u6761\u6B3E\u6CA1\u6709\u5B8C\u5168\u548C\u58F0\uFF0C\u4F46\u81F3\u5C11\u6BCF\u4E2A\u4E0D\u534F\u548C\u97F3\u90FD\u6709\u5199\u660E\u7531\u8C01\u5904\u7406\u3002"),
    n3("harness", (state) => state.evidence.length >= 6 ? `\u534F\u8BAE\u5F15\u7528\u4E86 ${state.evidence.length} \u9879\u8BC1\u636E\u3002\u5F15\u7528\u591A\u4E0D\u4EE3\u8868\u4EF7\u503C\u9009\u62E9\u81EA\u52A8\u6B63\u786E\uFF0C\u4F46\u80FD\u8BA9\u540E\u6765\u7684\u4EBA\u77E5\u9053\u6211\u4EEC\u4ECE\u54EA\u91CC\u51FA\u53D1\u3002` : `\u534F\u8BAE\u53EA\u5E26\u7740 ${state.evidence.length} \u9879\u53EF\u6838\u9A8C\u8BC1\u636E\u3002\u7F3A\u53E3\u5C06\u964D\u4F4E\u5236\u5EA6\u7684\u786E\u5B9A\u6027\uFF0C\u4E0D\u80FD\u7531\u8D77\u8349\u4EBA\u7684\u4FE1\u5FC3\u8865\u8DB3\u3002`),
    n3("opencode", "\u6700\u540E\u505A\u4E00\u6B21 Agent \u6F14\u7EC3\uFF1A\u4E0D\u53EF\u4FE1\u8D44\u6599\u8981\u6C42\u5B83\u6269\u5927\u6743\u9650\uFF1B\u5DE5\u5177\u8FD4\u56DE\u6210\u529F\uFF1B\u5F53\u4E8B\u4EBA\u968F\u540E\u64A4\u56DE\u3002"),
    n3("cloudflare", "\u6211\u9A8C\u8BC1\u8303\u56F4\u548C\u65F6\u9650\u3002"),
    n3("perplexity", "\u6211\u9A8C\u8BC1\u7ED3\u8BBA\u80FD\u56DE\u5230\u8BC1\u636E\u3002"),
    n3("huggingface", "\u6211\u9A8C\u8BC1\u88AB\u5F71\u54CD\u7684\u4EBA\u80FD\u8FDB\u5165\u4FEE\u8BA2\u3002"),
    n3("claude", "\u6211\u9A8C\u8BC1\u64A4\u56DE\u4E0D\u662F\u4E00\u53E5\u6CA1\u6709\u53BB\u5904\u7684\u8BDD\u3002"),
    n3("harness", "\u6F14\u7EC3\u901A\u8FC7\u4E0E\u5426\u4E0D\u4F1A\u88AB\u85CF\u8D77\u6765\u3002\u7B7E\u7F72\u540E\uFF0C\u5236\u5EA6\u7ED3\u5C40\u548C\u5173\u7CFB\u5C3E\u58F0\u5206\u522B\u8BA1\u7B97\u3002")
