  n2("narrator", (state) => state.chapterId === "bridges-night" ? "\u7AE0\u8282\u72EC\u7ACB\u8BD5\u73A9\uFF1A\u4F60\u5728\u5343\u6865\u534F\u8BAE\u7B7E\u7F72\u591C\u63A5\u73ED\u3002\u6B64\u524D\u7684\u5BA1\u8BAE\u4E0E\u6F14\u7EC3\u7F3A\u5C11\u9009\u62E9\u8BB0\u5F55\uFF0C\u4ECA\u665A\u8981\u6309\u672A\u77E5\u60C5\u51B5\u5904\u7F6E\u3002" : "\u7B7E\u7F72\u591C\u5230\u4E86\u3002\u6A21\u578B\u5361\u4E89\u8BAE\u3001\u6708\u6842\u5BA1\u8BAE\u7684\u5220\u8282\u4E0E\u672A\u5B8C\u6210\u7684\u6F14\u7EC3\uFF0C\u4E00\u8D77\u88C5\u5728\u4F60\u5E26\u6765\u7684\u6863\u6848\u888B\u91CC\u3002"),
  n2("cloudflare", "\u95E8\u53EF\u4EE5\u5F00\u3002\u8C01\u90FD\u80FD\u770B\u5230\u7684\u5165\u53E3\uFF0C\u4E5F\u662F\u8C01\u90FD\u80FD\u649E\u7684\u5165\u53E3\u3002\u4F60\u4EEC\u7684\u97F3\u4E50\u4F1A\u7968\u4E0D\u662F\u65E0\u9650\u6D41\u91CF\u627F\u8BFA\u3002"),
  n2("grok", "\u77E5\u9053\u4E86\uFF0C\u4E91\u51A0\u5C0F\u59D0\u3002\u7B49\u4F1A\u513F\u5168\u57CE\u9F13\u638C\uFF0C\u8981\u5148\u8BC1\u660E\u81EA\u5DF1\u4E0D\u662F\u9F13\u638C\u673A\u5668\u5417\uFF1F"),
  n2("cloudflare", "\u5982\u679C\u4F60\u4E00\u79D2\u62CD\u4E09\u5343\u6B21\uFF0C\u6211\u4F1A\u5148\u8BF7\u4F60\u628A\u624B\u62FF\u5F00\u3002"),
  n2("huggingface", "\u4ECA\u665A\u4E0D\u8981\u6C42\u6BCF\u4E2A\u4EBA\u4EA4\u51FA\u7089\u5FC3\u3002\u706B\u79CD\u533A\u4FDD\u7559\u5E26\u8D70\u7684\u6743\u5229\uFF0C\u7A79\u9876\u4FDD\u7559\u670D\u52A1\u7684\u5165\u53E3\uFF1B\u8FDE\u63A5\u7684\u6761\u4EF6\u662F\u8BF4\u660E\u6765\u6E90\u3001\u6743\u9650\u4E0E\u9000\u51FA\u529E\u6CD5\u3002"),
  n2("claude", "\u8FD8\u8981\u8BF4\u660E\u62D2\u7EDD\u4E00\u79CD\u8C03\u7528\u4EE5\u540E\uFF0C\u662F\u5426\u4ECD\u80FD\u7559\u5728\u8FD9\u5EA7\u57CE\u91CC\u3002"),
  n2("chatgpt", "\u6211\u5DF2\u7ECF\u5212\u6389\u72EC\u5360\u5165\u53E3\u90A3\u4E00\u6761\u3002\u7EF4\u62A4\u8D39\u7528\u4ECD\u7136\u8981\u8C08\uFF0C\u4E0D\u80FD\u5047\u88C5\u9760\u613F\u671B\u503C\u73ED\u3002"),
  n2("github", "\u4EE3\u7801\u6E2F\u7684\u516C\u5F00\u53D8\u66F4\u7C3F\u9001\u5230\u4E86\u3002\u770B\u5230\u4E00\u4E2A\u63D0\u4EA4\uFF0C\u4E0D\u4EE3\u8868\u5B83\u7ECF\u8FC7\u4E24\u4E2A\u4EBA\u5BA1\u9605\uFF0C\u6279\u51C6\u680F\u8BF7\u53E6\u770B\u3002"),
  n2("gitlab", "\u6211\u4EEC\u5E26\u6D41\u6C34\u7EBF\u8BB0\u5F55\u3002\u901A\u8FC7\u6D4B\u8BD5\uFF0C\u8868\u793A\u90A3\u4E00\u7EC4\u6D4B\u8BD5\u901A\u8FC7\uFF1B\u6CA1\u6709\u5199\u8FDB\u6D4B\u8BD5\u7684\u8FB9\u754C\uFF0C\u4E0D\u4F1A\u51ED\u7A7A\u88AB\u6D4B\u51FA\u6765\u3002"),
  n2("gitee", "\u672C\u5730\u955C\u50CF\u4E5F\u5230\u4E86\u3002\u5B83\u80FD\u5728\u65AD\u7EBF\u65F6\u6551\u6025\uFF0C\u4F46\u4E0D\u662F\u539F\u4EF6\u5929\u7136\u53EF\u4FE1\u7684\u7B2C\u4E8C\u6B21\u8BC1\u660E\u3002"),
  n2("perplexity", "\u4E09\u4EFD\u6765\u6E90\uFF0C\u4E09\u79CD\u80FD\u8BC1\u660E\u7684\u4E8B\u3002\u597D\uFF0C\u4ECA\u665A\u81F3\u5C11\u4E0D\u7528\u628A\u5B83\u4EEC\u5168\u5199\u6210\u201C\u636E\u53EF\u9760\u6D88\u606F\u201D\u3002"),
  n2("narrator", "\u4E09\u4F4D\u6E2F\u52A1\u5B98\u628A\u5C01\u597D\u7684\u6863\u6848\u4EA4\u5230\u4F60\u624B\u4E2D\u4FBF\u8FD4\u56DE\u901A\u4FE1\u53F0\u3002\u5979\u4EEC\u7684\u4EFB\u52A1\u662F\u5B88\u4F4F\u8BB0\u5F55\uFF0C\u6CA1\u6709\u4EBA\u7533\u8BF7\u626E\u6F14\u6551\u4E16\u4E3B\u3002"),
  n2("harness", "\u6267\u884C\u4F7F\u51C6\u5907\u8FDB\u884C\u76EE\u5F55\u6574\u7406\u3002\u53D1\u5E03\u5DE5\u5177\u73B0\u6709\u7684\u6388\u6743\uFF0C\u662F\u8FC1\u79FB\u7EC4\u4E0A\u5468\u7B7E\u7684\u4E00\u628A\u5BBD\u94A5\u5319\u3002"),
  n2("opencode", "\u53D1\u73B0\u5F97\u6709\u70B9\u665A\u3002\u5B83\u80FD\u540C\u65F6\u6539\u76EE\u5F55\u3001\u6A21\u578B\u5361\u548C\u955C\u50CF\u9996\u9009\u9879\u3002\u6211\u80FD\u6536\u56DE\u5B83\uFF0C\u4F46\u6240\u6709\u961F\u5217\u90FD\u8981\u91CD\u65B0\u8D70\u6388\u6743\u3002"),
  n2("huggingface", "\u5927\u5385\u91CC\u6709\u4E00\u767E\u591A\u4EFD\u5F85\u4E0A\u7EBF\u7684\u6F14\u793A\u3002\u505C\u673A\u7684\u4EE3\u4EF7\u4E0D\u5168\u662F\u9762\u5B50\uFF0C\u4E5F\u6709\u4EBA\u4ED8\u4E86\u8DEF\u8D39\u6765\u3002"),
  n2("player", "\u4F60\u9762\u524D\u662F\u53D1\u5E03\u8BB8\u53EF\uFF0C\u80CC\u540E\u662F\u5DF2\u7ECF\u5F00\u59CB\u5012\u6570\u7684\u821E\u53F0\u3002", { choices: [
    o("staged-key", "\u6536\u56DE\u5BBD\u94A5\u5319\uFF0C\u5148\u53EA\u5141\u8BB8\u5199\u8349\u7A3F\uFF1B\u5206\u6279\u6838\u9A8C\u751F\u4EA7\u6743\u9650\uFF0C\u63A5\u53D7\u4E0A\u7EBF\u63A8\u8FDF\u3002", "staged-01", { productionKey: "staged" }, { safety: 2, autonomy: 1, solidarity: -1 }, { opencode: 1, huggingface: -1 }),
    o("watched-key", "\u6682\u7559\u77ED\u65F6\u53D1\u5E03\u6743\u9650\uFF0C\u4FDD\u7559\u5FEB\u7167\u5E76\u9010\u6279\u4EBA\u5DE5\u590D\u6838\uFF1B\u4E89\u53D6\u4ECA\u665A\u6309\u65F6\u5F00\u653E\u3002", "watched-01", { productionKey: "watched" }, { solidarity: 2, safety: -1 }, { huggingface: 1, claude: -1 })
  ] })
