  n2("opencode", "\u6BCF\u4E00\u6279\u4F1A\u5148\u505C\u5728\u5DE5\u5177\u53F0\u3002\u5916\u90E8\u955C\u50CF\u7684\u65E2\u6709\u961F\u5217\u4E0D\u5F52\u8FD9\u53F0\u9501\u76F4\u63A5\u7BA1\uFF0C\u6211\u6B63\u5728\u67E5\u3002"),
  n2("harness", "\u5F53\u524D\u4EBA\u624B\u53EA\u80FD\u5B88\u4F4F\u4E3B\u7AD9\u3002\u5DF2\u63D0\u9192\u4E24\u7AEF\u8D1F\u8D23\u4EBA\u6682\u7F13\u955C\u50CF\u540C\u6B65\u3002")
